window.DRL = {"D":[{"id":"a1","c":"arm","n":"Pre-Throw Stretch: Hips, Back, Shoulders","t":8,"lv":1,"who":"solo","where":"inside","eq":"Floor space","why":"Loosens hips, back and shoulders. Always first, before anything else.","steps":["Hip 90/90: sit with both knees bent at 90°, switch sides slowly. 10 each way.","ATG lunge: long lunge, back knee down, push the front knee forward. 8 each leg.","Cat-cow (spinal hygiene): on hands and knees, round your back, then arch. 10 slow.","Yoga push-up to cobra: push hips up, then drop hips and look up. 5 slow.","Wall windmill: side to a wall, draw a big circle with your arm. 8 each side.","Shoulder taps: push-up position, tap opposite shoulder. 10 each."],"cues":["Slow and smooth","Breathe out as you stretch","Nothing should hurt"],"game":"Race the clock: can you do every move with perfect form in 8 minutes?","v":"https://www.youtube.com/watch?v=Ge6Dm0HcE0Y","cl":"Mobility A–D","aka":"Cleary Mobility (12U)","s":540,"e":595},{"id":"a2","c":"arm","n":"Body Warm-Up Before Throwing","t":6,"lv":1,"who":"solo","where":"yard","eq":"Light ball or 2 lb med ball","why":"Gets your body moving in the right order before you pick up a baseball.","steps":["Front Load & Ride x5 each side.","Inward Turn x5 each side.","Reverse Lunge to Throw x3 each side.","Bauers x3 each side.","Follow the coach's video for each move. Go at half speed; this is a warm-up, not a workout."],"cues":["Legs first, arm last","Stay smooth","Light ball only"],"game":"Mirror it: do each move in front of a mirror and try to copy the video exactly.","v":"https://www.youtube.com/watch?v=jBQcKd1F8wU","cl":"Pre-Throw 1–3","aka":"Cleary Pre-Throw (12U)"},{"id":"a3","c":"arm","n":"Backward Toss Into a Wall (Warm-Up)","t":3,"lv":1,"who":"solo","where":"yard","eq":"Baseball or soft ball, wall or net","why":"First move of the Cleary plyo warm-up. Wakes up the back of your shoulder.","steps":["Stand with your back to the wall, a few steps away.","Hold the ball out front, then throw it backward over your shoulder into the wall.","Easy effort. 10 throws."],"cues":["Easy, not hard","Elbow stays up","Finish tall"],"game":"Count how many of 10 hit the wall in the same spot.","v":"https://www.youtube.com/watch?v=HuP_mNVO3wk","cl":"Plyo 1–3","aka":"Reverse Throw"},{"id":"a4","c":"arm","n":"Loose Arm Flips Into a Wall (Warm-Up)","t":3,"lv":1,"who":"solo","where":"yard","eq":"Baseball or soft ball, wall or net","why":"Lets your arm find its own smooth path.","steps":["Stand sideways to the wall.","Let your arm swing through its natural throwing circle and flip the ball into the wall.","8 each. Keep it loose and easy."],"cues":["Loose arm","Let it swing","No muscling"],"game":"Try it with your eyes closed for 3 reps and feel the path.","v":"https://www.youtube.com/watch?v=jcxaXfLfeR0","cl":"Plyo 1–3","aka":"Arm Action Freestyle","e":60},{"id":"a5","c":"arm","n":"Turn and Throw, Feet Planted (Warm-Up)","t":3,"lv":1,"who":"solo","where":"yard","eq":"Baseball or soft ball, wall or net","why":"Teaches your chest and hips to turn before your arm goes.","steps":["Stand with your chest facing the wall, feet wide.","Turn your shoulders back, then rotate and throw without moving your feet.","5 throws at easy-to-medium effort."],"cues":["Turn, then throw","Feet stay planted","Chest finishes at the target"],"game":"Put a target on the wall. 5 throws, how many hits?","v":"https://www.youtube.com/watch?v=Ush3Utf-IV4","cl":"Plyo 1–3","aka":"Pivot Pick-Off","e":53},{"id":"a6","c":"arm","n":"Overhead Circle Throws (Warm-Up)","t":3,"lv":2,"who":"solo","where":"yard","eq":"Baseball or soft ball, wall or net","why":"Builds a smooth, connected arm circle.","steps":["Follow the coach's video.","5 throws, medium effort."],"cues":["Smooth circle","Stay relaxed"],"game":"","v":"https://youtube.com/shorts/-3hDwmw6dSE","cl":"Plyo 1–2","aka":"Lasso"},{"id":"a7","c":"arm","n":"Figure-8 Rock and Throw (Warm-Up)","t":3,"lv":2,"who":"solo","where":"yard","eq":"Baseball or soft ball, wall or net","why":"Adds rhythm and weight shift to your throw.","steps":["Stand sideways, feet wide.","Draw a figure 8 with the ball while you rock back and forth.","On the last rock forward, throw. 3 each."],"cues":["Rock back, rock forward","Stay sideways","Throw on rhythm"],"game":"Say 'back, front, throw' out loud to keep the rhythm.","v":"https://youtube.com/shorts/s-d9JnQuk7g","cl":"Plyo 1–2","aka":"Figure 8 Rocker"},{"id":"a8","c":"arm","n":"Full-Effort Turn and Throw (Last Warm-Up)","t":3,"lv":3,"who":"solo","where":"yard","eq":"Baseball, wall or net","why":"The last and fastest plyo drill. Only on high days.","steps":["Follow the coach's video.","3 throws. This is the only one that gets close to full effort."],"cues":["Full warm-up first","Stay on line"],"game":"","v":"https://www.youtube.com/shorts/mx7phLOIKnM","cl":"Plyo 1","aka":"Turn & Burns"},{"id":"a9","c":"arm","n":"After Throwing: Shoulder Blade I-Y-T-W","t":6,"lv":1,"who":"solo","where":"inside","eq":"Floor","why":"Arm care after you throw. Builds the small muscles behind your shoulder.","steps":["Lie face down. Lift arms into an I, hold 5 seconds. 10 reps.","Same for Y, then T, then W. No weight.","Finish with 2 x 30 seconds squeezing a tennis ball (forearm)."],"cues":["Thumbs up","Squeeze shoulder blades","Slow"],"game":"Have someone balance a paper cup on your back. Don't spill it.","v":"","cl":"Scap 1–3","aka":"Post-Throw: Scap","nov":1},{"id":"a10","c":"arm","n":"After Throwing: Band Shoulder Strength","t":6,"lv":2,"who":"solo","where":"inside","eq":"Light band","why":"Arm care after you throw. Keeps your shoulder strong and steady.","steps":["Band pull-aparts: 2 x 12.","ER walk-outs: band at elbow height, elbow at your side, step away and hold. 2 x 8.","Elbow stays glued to your ribs."],"cues":["Light band","Slow both ways","Stop if it pinches"],"game":"","v":"https://www.youtube.com/watch?v=awSMT7PlZ5A","cl":"Rotator Cuff 2","aka":"Post-Throw: Rotator Cuff","s":68,"e":121},{"id":"a11","c":"arm","n":"After Throwing: Slow Arm Circles","t":5,"lv":1,"who":"solo","where":"inside","eq":"None","why":"Arm care after you throw. Keeps your shoulder and elbow moving freely.","steps":["Shoulder CARs: biggest, slowest arm circle you can. 5 each way.","Elbow CARs: bend, turn palm up and down, straighten. 10.","Scap CARs: shrug up, back, down, forward. 10.","Thoracic extension over a chair back or foam roller. 10."],"cues":["Slow circles","Rest of your body stays still"],"game":"","v":"https://www.youtube.com/watch?v=EunHAooYktE","cl":"Mobility 1–3","aka":"Post-Throw: Mobility","s":166,"e":181},{"id":"t1","c":"throw","n":"Four-Seam Grip Check","t":3,"lv":1,"who":"solo","where":"inside","eq":"Baseball","why":"A four-seam grip makes the ball fly straight.","steps":["Toss the ball up and catch it.","Without looking, find the horseshoe and put two fingers across the seams.","Check. 20 tosses."],"cues":["Fingers across the horseshoe","Thumb underneath","Hold it like an egg"],"game":"Race a sibling: who gets 10 perfect grips first?","v":"https://www.youtube.com/watch?v=nCUsWBYVUyA","cl":"","s":15,"e":75},{"id":"t2","c":"throw","n":"One-Knee Throws","t":5,"lv":1,"who":"partner","where":"yard","eq":"Baseball, glove","why":"Takes your legs away so you can feel your arm path and release.","steps":["Glove-side knee down (righty: left knee), throwing-side foot planted a little in front of that knee, about 20–25 feet apart.","Ball in the middle of your body. Turn so your throwing shoulder points back and your front shoulder points at your partner.","Break your hands, throw to your partner's chest and follow through across your body. 10–15 throws."],"cues":["Point your glove at the target","Let the arm follow through, don't stop it","Finish moving toward the target"],"game":"Chest = 2 points, head = 1. First to 15.","v":"https://www.youtube.com/watch?v=jy0UwFdlw9M","cl":"","s":18,"e":76},{"id":"t3","c":"throw","n":"Sideways Stance Throws","t":5,"lv":1,"who":"partner","where":"yard","eq":"Baseball, glove","why":"Starts you in the strongest spot of the throw.","steps":["Stand sideways, feet wider than shoulders, arms in a T.","Shift back, then forward and throw.","15 throws at 30–40 feet."],"cues":["Sideways first","Back to front","Chest over front knee"],"game":"","v":"https://www.youtube.com/watch?v=77r6mWAUecA","cl":"","aka":"Power Position Throws","s":66,"e":100},{"id":"t5","c":"throw","n":"Step-Behind Throws","t":5,"lv":2,"who":"partner","where":"field","eq":"Baseball, glove","why":"Adds momentum, like an infielder making a play.","steps":["Catch the ball, step your back foot behind your front foot.","Stay sideways, then throw through your partner.","15 throws at 50–60 feet."],"cues":["Gain ground","Stay closed","Throw through, not to"],"game":"","v":"https://www.youtube.com/watch?v=ziloiv9u89w","cl":"","e":60},{"id":"t6","c":"throw","n":"Throw at a Taped Square on a Wall","t":8,"lv":1,"who":"solo","where":"yard","eq":"Tennis or rubber ball, wall, tape or chalk","why":"Accuracy beats arm strength. This is the best solo drill there is.","steps":["Tape or chalk a square about chest high.","Start 20 feet away. Throw 10.","Hit 7 of 10? Take two steps back."],"cues":["Pick a small spot","Same motion every time"],"game":"Play 21: square = 2 points, close = 1. How few throws to reach 21?","v":"https://www.youtube.com/watch?v=lOt4pnucO2g","cl":"","aka":"Wall Ball Target","s":28,"e":60},{"id":"t7","c":"throw","n":"Fast Catch-and-Throw (30 Seconds)","t":5,"lv":2,"who":"partner","where":"yard","eq":"Baseball, glove","why":"Gets the ball out of your glove fast.","steps":["Stand 15–20 feet apart.","Catch and throw as fast as you can with good throws.","30 seconds, count the catches. Rest and repeat 3 times."],"cues":["Catch in the middle","Two hands","Short steps"],"game":"Beat your count every round.","v":"https://www.youtube.com/watch?v=77r6mWAUecA","cl":"","aka":"Quick Hands","s":133,"e":169},{"id":"t8","c":"throw","n":"Catch With Points: First to 21","t":8,"lv":1,"who":"partner","where":"yard","eq":"Baseball, glove","why":"Makes every throw of catch count.","steps":["Play catch about 45–60 feet apart (closer if you're younger).","Your partner holds the glove still as a target at the chin/chest.","Catch it without moving the glove = 2 points. Glove moves a little but still in the chest-chin area = 1. Anywhere else = 0.","First to 21 wins."],"cues":["Hold the target still","Aim small, miss small","Stay square to your partner"],"game":"It already is one. Loser carries the bucket.","v":"https://www.youtube.com/watch?v=K_XToSAhmhc","cl":"","aka":"Catch Play 21","s":42,"e":100},{"id":"t9","c":"throw","n":"Long Toss: Back Up Every 5 Throws","t":10,"lv":2,"who":"partner","where":"field","eq":"Baseball, glove","why":"Builds arm strength the safe way: stretch it out, then come back in.","steps":["Start at 30 feet. 5 throws.","Step back 10 feet every 5 throws. Keep an easy arc.","Stop at the last distance you can reach on a line with no pain.","Come back in the same way."],"cues":["Easy arc going out","On a line coming in","Never through pain"],"game":"Count total catches without a drop on the way back in.","v":"https://www.youtube.com/watch?v=jy0UwFdlw9M","cl":"Catch play","aka":"Long Toss Ladder (12U)","s":400,"e":458},{"id":"t10","c":"throw","n":"Hop-Step Long Throws","t":6,"lv":2,"who":"partner","where":"field","eq":"Baseball, glove","why":"How outfielders and infielders get everything behind a long throw.","steps":["Catch, then hop: back foot replaces front foot.","Land sideways, throw.","10 throws at 60–80 feet."],"cues":["Hop forward, not up","Stay sideways","Follow your throw"],"game":"","v":"https://www.youtube.com/watch?v=g7Oa9ntktVw","cl":"","aka":"Crow Hop Throws","s":55,"e":113},{"id":"t11","c":"throw","n":"Relay Race Throwing Line","t":8,"lv":2,"who":"team","where":"field","eq":"Baseballs, gloves","why":"Team throwing under a little pressure.","steps":["Lines of 4, each player 40–50 feet apart.","Ball goes down the line and back. Turn glove side.","Race the other lines."],"cues":["Hands up, yell 'hit me'","Turn glove side","Quick feet"],"game":"First line to finish 3 trips wins.","v":"https://www.youtube.com/watch?v=Yle6R1-flA8","cl":"","aka":"Relay Line","s":83,"e":142},{"id":"t12","c":"throw","n":"One-Hop Throws Into a Bucket","t":5,"lv":1,"who":"solo","where":"yard","eq":"Bucket, 10 balls","why":"Touch and feel, like a throw to a base.","steps":["Set a bucket on its side 30–40 feet away.","Throw so the ball takes one hop into the bucket.","10 throws."],"cues":["One hop","Aim small"],"game":"Keep a high score on the bucket with tape.","v":"","cl":"","aka":"Bucket Toss","nov":1},{"id":"p1","c":"pitch","n":"Leg Lift Balance Holds","t":4,"lv":1,"who":"solo","where":"inside","eq":"None","why":"Every good delivery passes through balance.","steps":["From the stretch, lift your front knee to your belt.","Hold for 3 seconds without wobbling.","10 reps. Then 5 with your eyes closed."],"cues":["Tall, not leaning","Hands in the middle","Eyes on the target"],"game":"Who can hold it longest?","v":"https://www.youtube.com/watch?v=R-NcEhJYIlc","cl":"","aka":"Balance Point Holds","s":40,"e":100},{"id":"p3","c":"pitch","n":"Rock Back, Rock Forward Throws","t":5,"lv":1,"who":"partner","where":"yard","eq":"Baseball, glove","why":"Rhythm and weight shift.","steps":["Stride position, feet already apart.","Rock back, rock forward, throw.","15 throws."],"cues":["Back, forward, throw","Head stays over your belt"],"game":"","v":"https://www.youtube.com/watch?v=77r6mWAUecA","cl":"","aka":"Rocker Throws","s":66,"e":100},{"id":"p4","c":"pitch","n":"Stride Straight on a Line","t":5,"lv":1,"who":"solo","where":"yard","eq":"Tape or chalk line","why":"Teaches you to go straight to the plate.","steps":["Make a line from the middle of your back foot toward the target.","Do your delivery with no ball.","Check: did your front foot land on the line? 10 reps."],"cues":["Stride to the plate","Land soft","Toes at the target"],"game":"10 in a row on the line.","v":"https://www.youtube.com/watch?v=LlyXy2W8jWs","cl":"","aka":"Stride Line","s":18,"e":76},{"id":"p5","c":"pitch","n":"Walk-In Windup Throws","t":5,"lv":2,"who":"partner","where":"field","eq":"Baseball, glove","why":"Momentum toward the plate.","steps":["Take a walking step behind, then go into your leg lift without stopping.","Throw to your partner.","10 throws."],"cues":["Keep moving","Don't rush your arm"],"game":"","v":"https://www.youtube.com/watch?v=atOQzaC50ZM","cl":"","aka":"Walking Windup","s":347,"e":377},{"id":"p6","c":"pitch","n":"Hit 3 Spots: 9-Pitch Strike Test","t":8,"lv":2,"who":"partner","where":"field","eq":"Baseball, catcher or target","why":"Command wins at 12U. Fastballs for strikes.","steps":["Flat ground or mound, at your game distance.","Throw 3 to the glove side, 3 middle, 3 arm side.","Count strikes out of 9."],"cues":["Same delivery to every spot","Eyes on the glove"],"game":"Beat your score. 7 of 9 is an ace.","v":"","cl":"","aka":"Strike Zone 3x3","nov":1},{"id":"p7","c":"pitch","n":"Changeup Grip Catch","t":6,"lv":2,"who":"partner","where":"yard","eq":"Baseball, glove","why":"A changeup is the best second pitch at this age. Same arm speed, different grip.","steps":["Put your middle two fingers on top of the ball between the seams, thumb underneath. Squeeze them together like one big finger.","Hold the ball a little deeper in your hand than a fastball.","Play catch at 40 feet with only that grip and the same arm speed as your fastball. 15 throws."],"cues":["Same arm speed as the fastball","Fingers together","Thumb underneath"],"game":"Have your partner guess: fastball or changeup?","v":"https://www.youtube.com/watch?v=9CzbPIQfXmM","cl":"","aka":"Changeup Feel","e":58},{"id":"p8","c":"pitch","n":"Short Bullpen: 20 Pitches","t":12,"lv":3,"who":"partner","where":"field","eq":"Mound, catcher","why":"A short, planned bullpen. Fastball and changeup only.","steps":["Full warm-up first.","10 fastballs: 5 glove side, 5 arm side.","5 changeups.","5 fastballs: catcher calls the spot. Count strikes."],"cues":["Stay at 20","Quality over quantity","Arm care after"],"game":"Strike on the last pitch or you owe the catcher a high five.","v":"https://www.youtube.com/watch?v=atOQzaC50ZM","cl":"Bullpen day","aka":"Bullpen: 20-Pitch Plan","s":660,"e":718},{"id":"p9","c":"pitch","n":"Pitcher Runs to Cover First Base","t":6,"lv":2,"who":"team","where":"field","eq":"Baseballs, bases","why":"Pitchers are fielders too.","steps":["Ball rolled to the first-base side. Sprint on a direct angle toward first base.","Stay out of the runner's path: get to the inside of the base and show your target.","Take the feed from the first baseman as early as you can, touch the inside of the bag, then turn back out of the base path into a ready position. 5 reps."],"cues":["Direct angle, full sprint","Touch the inside of the base","Get out of the runner's way"],"game":"","v":"https://www.youtube.com/watch?v=pss8tFhJdh4","cl":"","aka":"PFP: Cover First","e":60},{"id":"h1","c":"hit","n":"Mirror Swings (No Ball)","t":5,"lv":1,"who":"solo","where":"inside","eq":"Bat, mirror or window","why":"See your own swing. Great pros still do this.","steps":["Stand where you can see your reflection.","10 slow-motion swings, 10 at game speed.","Check: balanced finish every time?"],"cues":["Athletic stance","Head still","Finish balanced"],"game":"Freeze at contact. Is your back knee pointing at the pitcher?","v":"https://www.youtube.com/watch?v=_yz-Jq8Tbmc","cl":"","aka":"Dry Swings (Mirror)","s":150,"e":208},{"id":"h2","c":"hit","n":"Tee Work: Line Drives Up the Middle","t":8,"lv":1,"who":"solo","where":"yard","eq":"Tee, balls, net or fence","why":"The tee is where swings get built.","steps":["Tee at belt height, even with your front foot.","Hit line drives back up the middle.","2 sets of 10."],"cues":["Line drive, not ground ball","Hit the inside of the ball"],"game":"Line drives count 1, everything else 0. Beat your best of 10.","v":"https://www.youtube.com/watch?v=-WVsyQFNx5A","cl":"","aka":"Tee: Middle","s":26,"e":86},{"id":"h3","c":"hit","n":"Tee Work: Inside and Outside Pitches","t":8,"lv":2,"who":"solo","where":"yard","eq":"2 tees, balls, net","why":"Learn where to hit each pitch.","steps":["Set two tees: the inside tee further out in front, the outside tee deeper. Make them slightly different heights.","Get in your stance. As you start your swing, a helper calls “in” or “out.”","Hit the one they call: pull the inside ball, drive the outside ball the other way. 10 swings."],"cues":["Helper calls it early, not late","Get to a strong 50/50 position","Let the outside ball travel"],"game":"Call your field before you swing.","v":"https://www.youtube.com/watch?v=KaaMP4a2ZvQ","cl":"","aka":"Tee: Inside / Outside","s":64,"e":122},{"id":"h4","c":"hit","n":"One-Hand Tee Swings","t":6,"lv":2,"who":"solo","where":"yard","eq":"Tee, short bat or choke up","why":"Each hand has a job.","steps":["Bottom hand only: 8 swings off the tee.","Top hand only: 8 swings.","Both hands: 8 swings."],"cues":["Short to the ball","Stay through it"],"game":"","v":"https://www.youtube.com/watch?v=ZdxaI4fd95c","cl":"","aka":"Top Hand / Bottom Hand","s":40,"e":100},{"id":"h5","c":"hit","n":"Stride and Freeze (Load Check)","t":5,"lv":2,"who":"solo","where":"inside","eq":"Broomstick or PVC pipe","why":"Getting to a strong launch position on time.","steps":["Stand the stick straight up just outside the toes of your back foot and hold it where you'd hold the bat.","Take your normal stride toward the pitcher without letting the stick move.","Stick tipped forward? You drifted. Stick tipped back? You leaned. 10 strides, then 10 dry swings."],"cues":["Hands stay back","Stride, don't drift","Land athletic"],"game":"","v":"https://www.youtube.com/watch?v=IOmP3TPLsX0","cl":"","aka":"Stride and Separate","e":60},{"id":"h6","c":"hit","n":"Side Soft Toss Into a Net","t":8,"lv":1,"who":"partner","where":"yard","eq":"Balls, net, helper","why":"Timing a moving ball.","steps":["Helper kneels to the side and a little in front.","Soft underhand toss into the zone.","2 sets of 10 line drives."],"cues":["See it, then swing","Same swing as the tee"],"game":"Helper calls 'high' or 'low' mid-toss; adjust.","v":"https://www.youtube.com/watch?v=rV3EQ5tHcNE","cl":"","aka":"Soft Toss","e":60},{"id":"h7","c":"hit","n":"Front Toss Behind a Screen","t":10,"lv":2,"who":"partner","where":"field","eq":"L-screen, balls, helper","why":"The closest thing to live pitching.","steps":["Helper tosses firm underhand from 15–20 feet behind a screen.","Hit hard line drives.","3 rounds of 8."],"cues":["Be on time","Hit it where it's pitched"],"game":"Line drive past the screen = 1 point.","v":"https://www.youtube.com/watch?v=2xX6uWyEuKc","cl":"","s":60,"e":118},{"id":"h8","c":"hit","n":"Stride, Pause, Swing (Stops Lunging)","t":6,"lv":3,"who":"solo","where":"yard","eq":"Tee, balls","why":"Fixes lunging.","steps":["Stride and pause for a full second.","Then swing.","10 swings."],"cues":["Stay back","Head between your feet"],"game":"","v":"https://www.youtube.com/watch?v=6T5KqcXHyEw","cl":"","aka":"Pause Drill","e":60},{"id":"h9","c":"hit","n":"Bunt Between Cones","t":6,"lv":1,"who":"partner","where":"field","eq":"Bat, balls, 4 cones","why":"Bunting wins games at 12U.","steps":["Make two cone gates: one up each line.","Pivot, bat out front, catch the ball with the bat.","10 bunts. Through a gate = 1 point."],"cues":["Bat head above hands","Bend knees for low pitches","Catch the ball with the bat"],"game":"Play to 5 against a teammate.","v":"https://www.youtube.com/watch?v=EbQc9NDEpRk","cl":"","aka":"Bunt to the Cones","s":150,"e":210},{"id":"h10","c":"hit","n":"Two-Strike Survival: Stay Alive","t":8,"lv":2,"who":"partner","where":"field","eq":"Front toss setup","why":"Putting the ball in play when you have to.","steps":["Choke up, widen out.","Every pitch near the zone you must swing.","Foul = alive. Miss = out. How many pitches can you stay alive?"],"cues":["Shorten up","Protect the plate"],"game":"Longest at-bat wins.","v":"","cl":"","aka":"Two-Strike Battle","nov":1},{"id":"h11","c":"hit","n":"Call the Number: See the Ball Early","t":5,"lv":1,"who":"partner","where":"yard","eq":"Helper","why":"Teaches you to see the ball out of the hand.","steps":["Helper goes through a throwing motion and holds up fingers at release.","Call the number as fast as you can.","15 reps."],"cues":["Eyes to the release point","Call it early"],"game":"Speed round: 10 in a row correct.","v":"","cl":"","aka":"Number Call (Pitch Tracking)","nov":1},{"id":"f1","c":"field","n":"Two-Hand Ground Balls","t":5,"lv":1,"who":"partner","where":"yard","eq":"Ball, glove","why":"Two hands on every ground ball.","steps":["Feet wide, bottom down, glove out front on the ground.","Partner rolls the ball. Clamp your bare hand on top like alligator jaws.","20 reps."],"cues":["Glove out front","Trap the ball like a clam shell","Bring it to your belly button"],"game":"10 clean in a row.","v":"https://www.youtube.com/watch?v=EGMSjpFMMkQ","cl":"","aka":"Alligator Hands","e":51},{"id":"f2","c":"field","n":"Ground Balls on Your Knees","t":5,"lv":1,"who":"partner","where":"yard","eq":"Ball, glove","why":"Forces you to field the ball out in front.","steps":["On both knees. Knees are the base of a triangle; your glove is the point.","Partner rolls balls. Field at the point, bring it to the middle.","15 reps."],"cues":["Field out front","Eyes behind the ball"],"game":"","v":"","cl":"","aka":"Knee Triangle","nov":1},{"id":"f3","c":"field","n":"Cap-Brim Grounders: Glove Out Front","t":4,"lv":1,"who":"partner","where":"yard","eq":"Ball, glove, cap","why":"Makes you watch the ball all the way in.","steps":["Flip your cap over and bite the brim so it sticks out.","Field rolled ground balls.","You can only see the ball if your glove is out front. 10 reps."],"cues":["Reach","Watch it in"],"game":"It looks silly. That's the fun.","v":"","cl":"","aka":"Hat Drill","nov":1},{"id":"f4","c":"field","n":"Grounders Off a Wall (Solo)","t":8,"lv":1,"who":"solo","where":"yard","eq":"Tennis ball, wall","why":"Hundreds of ground balls with nobody else.","steps":["Throw low against a wall.","Field it, get into throwing position, throw again.","3 minutes. Rest. 3 times."],"cues":["Stay low","Right-left (righty) through the ball"],"game":"Count clean ones in a row. Bobble = back to zero.","v":"https://www.youtube.com/watch?v=jBQar9CqGdA","cl":"","aka":"Wall Ball Grounders","e":60},{"id":"f5","c":"field","n":"Short Hop Catches","t":5,"lv":2,"who":"partner","where":"yard","eq":"Ball, glove","why":"Takes the fear out of the short hop.","steps":["Partner stands a few steps away and tosses the ball up so it will bounce in front of you.","Read it and go get it on the short hop, fielding it off your glove-side foot with one hand.","Stay loose with a little bounce in your feet. 10 forehand, then 10 backhand."],"cues":["Go get the short hop","Glove out front","Don't get stuck on the in-between hop"],"game":"First to miss does 5 jumping jacks.","v":"https://www.youtube.com/watch?v=nuvMnJ3RA3U","cl":"","aka":"Short Hop Picks","s":30,"e":90},{"id":"f6","c":"field","n":"Ground Ball Footwork Around Cones","t":6,"lv":2,"who":"solo","where":"yard","eq":"3 cones, ball","why":"Right-left-field, right-left-throw.","steps":["Cones in a triangle. Start at the back cone.","Step right, left, field at the front; right, left, throw.","10 reps, no ball, then 10 with a rolled ball."],"cues":["Work through the ball","Feet never stop"],"game":"","v":"https://www.youtube.com/watch?v=4UqDA8MfHes","cl":"","aka":"Triangle Footwork","s":237,"e":276},{"id":"f7","c":"field","n":"Throw Around the Square (Team)","t":8,"lv":2,"who":"team","where":"field","eq":"Baseballs, 4 bases","why":"Catching, footwork and throwing around a square.","steps":["A player at each corner, 40–60 feet apart.","Throw around the square, follow your throw.","Reverse on the whistle."],"cues":["Move your feet to the ball","Turn glove side"],"game":"How many in a row without a drop?","v":"https://www.youtube.com/watch?v=nTMZQsmpKBc","cl":"","aka":"Four Corners","e":60},{"id":"f8","c":"field","n":"Charge the Slow Roller","t":6,"lv":3,"who":"partner","where":"field","eq":"Baseballs","why":"The do-or-die play.","steps":["Coach rolls a slow ball.","Charge, field outside your glove-side foot, throw on the run.","5 reps."],"cues":["Charge under control","Field off the left foot (righty)","Throw across your body"],"game":"","v":"https://www.youtube.com/watch?v=MT778628suA","cl":"","aka":"Slow Roller","s":60,"e":118},{"id":"f9","c":"field","n":"Double Play Flips to Second","t":8,"lv":3,"who":"team","where":"field","eq":"Baseballs, base","why":"Shortstop and second base working together.","steps":["Rolled ball to short: underhand flip to second.","Rolled ball to second: pivot or backhand flip to short.","10 each."],"cues":["Show the ball","Follow your flip","Chest high"],"game":"","v":"https://www.youtube.com/watch?v=4aWrAxBqd7g","cl":"","aka":"Double Play Feeds","s":14,"e":74},{"id":"f10","c":"field","n":"Who Catches the Pop-Up? (Calling It)","t":6,"lv":2,"who":"team","where":"field","eq":"Tennis or baseballs","why":"Who calls it, and who gets out of the way.","steps":["Coach throws pop-ups between two players.","Loud 'Mine! Mine! Mine!' Other player peels off.","Outfielders have priority over infielders."],"cues":["Call it three times","Catch above your eyes"],"game":"Silent ball = both run a lap.","v":"https://www.youtube.com/watch?v=7k_-2lRG8YY","cl":"","aka":"Pop-Up Priority","s":50,"e":110},{"id":"f11","c":"field","n":"Rundown Defense: One Throw for the Out","t":8,"lv":2,"who":"team","where":"field","eq":"2 bases, ball","why":"Getting the out with as few throws as possible.","steps":["Runner between two bases, a fielder at each.","Run hard at the runner with the ball up.","Receiver calls 'now'. One throw is the goal."],"cues":["Ball up, no pump fakes","Run him back to the old base","Follow your throw"],"game":"Runners get a point for every safe; fielders for every out.","v":"https://www.youtube.com/watch?v=cV8Ivq0XcJA","cl":"","aka":"Rundown (Pickle)","s":218,"e":278},{"id":"o1","c":"of","n":"First Step Back on a Fly Ball","t":5,"lv":1,"who":"partner","where":"yard","eq":"Ball, glove","why":"First step back on a ball over your head.","steps":["Face your partner. They point left or right.","Drop that foot back, open your hips, run, then catch the toss.","8 each side."],"cues":["First step back","Run on your toes","Glove stays down until the end"],"game":"","v":"https://www.youtube.com/watch?v=qvwkdxepqTk","cl":"","aka":"Drop Step","s":10,"e":70},{"id":"o2","c":"of","n":"Call It: Fly Balls Between Two Players","t":6,"lv":1,"who":"team","where":"field","eq":"Tennis or baseballs","why":"No collisions, no dropped balls.","steps":["Two lines 30 feet apart.","Coach throws between them. One calls it, the other backs up.","10 each."],"cues":["Mine x3","Backup goes behind"],"game":"","v":"","cl":"","aka":"Fly Ball Communication","nov":1},{"id":"o3","c":"of","n":"Charge, Field and Throw Home (Outfield)","t":6,"lv":2,"who":"partner","where":"field","eq":"Baseballs","why":"Ground ball with the winning run trying to score.","steps":["Charge a rolled ball hard.","Field it outside your glove-side foot on the run.","Crow hop and throw low. 5 reps."],"cues":["Charge","Field off glove-side foot","Low throw, one hop"],"game":"","v":"https://www.youtube.com/watch?v=iUdI35veg5E","cl":"","aka":"Do or Die","s":25,"e":85},{"id":"o4","c":"of","n":"Tennis Ball Fly Balls","t":8,"lv":1,"who":"partner","where":"yard","eq":"Tennis ball, racket optional","why":"Lots of safe fly balls.","steps":["Helper throws or hits high tennis balls.","Catch with two hands above your eyes.","20 catches."],"cues":["Get behind it","Two hands","Thumb to thumb"],"game":"Catch 10 in a row to win.","v":"https://www.youtube.com/watch?v=Lnfgd_ld_CM","cl":"","s":108,"e":168},{"id":"o5","c":"of","n":"Outfield Throws to the Cutoff","t":8,"lv":2,"who":"team","where":"field","eq":"Baseballs","why":"A low throw to the cutoff beats a rainbow home.","steps":["Outfielder fields and crow hops.","Throw through the cutoff's head.","Cutoff has hands up and lines up with the base."],"cues":["Throw through the head","Low and on a line"],"game":"","v":"","cl":"","aka":"Hit the Cutoff","nov":1},{"id":"c1","c":"catch","n":"Catcher: Catch and Hold Low Pitches","t":6,"lv":1,"who":"partner","where":"yard","eq":"Catcher's mitt, balls","why":"Make strikes look like strikes.","steps":["Relaxed stance, mitt out front.","Partner tosses from 15 feet. Catch and hold for a second.","Low pitch: thumb under, work up through it. 20 catches."],"cues":["Quiet body","Beat the ball to the spot","Stick it"],"game":"","v":"https://www.youtube.com/watch?v=8EtK_1FoJgY","cl":"","aka":"Receiving: Thumb Under","s":13,"e":73},{"id":"c2","c":"catch","n":"Catcher: Block Balls in the Dirt","t":6,"lv":2,"who":"partner","where":"yard","eq":"Gear, soft balls","why":"Keeps runners from moving up.","steps":["From your stance, drop to both knees, mitt between your legs.","Chin down, shoulders rounded.","Partner short-hops soft balls. 10 middle, 5 each side."],"cues":["Knees down, mitt down, chin down","Deaden it in front"],"game":"Keep every ball inside a chalk circle.","v":"https://www.youtube.com/watch?v=Tjzv5anKEe0","cl":"","aka":"Blocking","s":8,"e":27},{"id":"c3","c":"catch","n":"Catcher: Quick Feet to Throw to Second","t":5,"lv":2,"who":"solo","where":"yard","eq":"Mitt, ball","why":"Fast, clean footwork for throwing to second.","steps":["Start in your stance with a ball in your mitt.","Pop to a throwing position: right foot replaces, left foot to the target.","10 reps without throwing, 5 with."],"cues":["Quick, not rushed","Ball to your ear","Stay low"],"game":"","v":"https://www.youtube.com/watch?v=wd8eYHPhAJA","cl":"","aka":"Pop Feet","s":62,"e":89},{"id":"c4","c":"catch","n":"Catcher: Pop-Ups With the Mask Off","t":4,"lv":2,"who":"partner","where":"field","eq":"Gear, balls","why":"Find it, turn your back to the field, catch it.","steps":["Helper throws a pop-up straight up.","Mask off, find the ball, toss the mask away from the ball.","Catch with two hands above your head. 6 reps."],"cues":["Find it first","Back to the infield"],"game":"","v":"","cl":"","aka":"Pop-Ups: Mask Off"},{"id":"r1","c":"run","n":"Run Through First","t":4,"lv":1,"who":"solo","where":"field","eq":"Base or a shirt","why":"Free hits come from running hard through the bag.","steps":["Swing, drop the bat, sprint.","Hit the front of the base, run through, then look right.","5 reps."],"cues":["Front of the bag","Don't slow down early","Peek right for an overthrow"],"game":"Time it. Beat your best.","v":"https://www.youtube.com/watch?v=bWt9YWZiJps","cl":"","s":23,"e":83},{"id":"r2","c":"run","n":"Round First for a Double","t":5,"lv":1,"who":"solo","where":"field","eq":"Base","why":"How to round first for a double.","steps":["Halfway down the line, bow out a little.","Touch the inside corner with either foot.","Find the ball. 5 reps."],"cues":["Bow out early","Inside corner","Eyes up"],"game":"","v":"https://www.youtube.com/watch?v=bWt9YWZiJps","cl":"","aka":"Question Mark Turn","s":106,"e":166},{"id":"r3","c":"run","n":"Take a Lead and Get Back","t":6,"lv":2,"who":"partner","where":"field","eq":"Base","why":"Getting a good lead and getting back safe (if your league allows leads).","steps":["Take your lead: left, right, shuffle, shuffle.","Helper yells 'back': dive or step back to the back corner.","8 reps."],"cues":["Never cross your feet","Eyes on the pitcher"],"game":"","v":"","cl":"","aka":"Leads and Returns","nov":1},{"id":"r4","c":"run","n":"Run on a Ball in the Dirt","t":6,"lv":2,"who":"team","where":"field","eq":"Balls, catcher","why":"Stealing a free base on a ball in the dirt.","steps":["Runner at first. Coach throws to a catcher.","Ball in the dirt: go on the bounce.","Caught clean: hustle back."],"cues":["Read the angle down","Go on the bounce"],"game":"","v":"","cl":"","aka":"Dirt Ball Read","nov":1},{"id":"r5","c":"run","n":"Tag Up and Score on a Fly Ball","t":5,"lv":1,"who":"team","where":"field","eq":"Balls","why":"Scoring on a fly ball.","steps":["Runner on third, foot on the bag.","Watch the catch yourself.","Go the instant it touches the glove."],"cues":["Foot on the base","Watch the catch","Explode"],"game":"","v":"","cl":"","nov":1},{"id":"r6","c":"run","n":"Go From First to Third","t":6,"lv":2,"who":"solo","where":"field","eq":"Bases","why":"Taking the extra base.","steps":["Start with a lead at first.","Hit second on the inside corner, pick up your third-base coach.","Finish standing or sliding. 4 reps."],"cues":["Look at the coach before second","Tight turns"],"game":"Timed. Fastest clean run wins.","v":"","cl":"","aka":"First to Third","nov":1},{"id":"r7","c":"run","n":"Learn to Slide (Pop-Up Slide)","t":6,"lv":2,"who":"solo","where":"yard","eq":"Grass or cardboard, long pants","why":"Sliding safely.","steps":["Start on wet grass or flattened cardboard.","Tuck one leg under into a figure 4, hands up.","Slide, then pop up on the bag. 6 reps."],"cues":["Hands up","Bottom, not side","Chin tucked"],"game":"","v":"https://www.youtube.com/watch?v=yRqqQGQt9FU","cl":"","aka":"Slide: Pop-Up","s":15,"e":75},{"id":"x1","c":"ath","n":"Moving Warm-Up Before Practice","t":6,"lv":1,"who":"solo","where":"yard","eq":"20 feet of space","why":"Wakes up your whole body before practice or a game.","steps":["High knees, butt kicks, side shuffles, carioca: 20 feet each.","Walking lunges with a twist x6 each.","Arm circles small to big x10 each way.","Two build-up sprints."],"cues":["Get a light sweat","Good posture"],"game":"","v":"","cl":"","aka":"Dynamic Warm-Up","nov":1},{"id":"x2","c":"ath","n":"Fast First 3 Steps","t":5,"lv":1,"who":"solo","where":"yard","eq":"Open space","why":"The first three steps win bases.","steps":["Athletic start position.","Explode for three hard steps, then coast.","8 reps, walk back each time."],"cues":["Push the ground away","Stay low","Arms drive"],"game":"Chalk a line. Did your third step beat last time?","v":"","cl":"","aka":"Speed: 3-Step Starts","nov":1},{"id":"x3","c":"ath","n":"Side-to-Side Shuffle and React","t":5,"lv":1,"who":"partner","where":"yard","eq":"2 cones","why":"Side-to-side quickness for fielding.","steps":["Cones 10 feet apart.","Partner points; you shuffle that way and touch the cone.","20 seconds on, 40 off, 4 rounds."],"cues":["Don't cross feet","Stay low","Chest up"],"game":"","v":"https://www.youtube.com/watch?v=Wm9vYLsJbi0","cl":"","aka":"Lateral Shuffle Reaction","s":50,"e":110},{"id":"x4","c":"ath","n":"Long Jump and Stick It","t":4,"lv":1,"who":"solo","where":"yard","eq":"Tape measure optional","why":"Power comes from your legs.","steps":["Feet shoulder width. Swing arms, jump as far as you can.","Stick the landing for 2 seconds.","6 jumps."],"cues":["Land soft","Knees over toes","Stick it"],"game":"Mark your best. Beat it next week.","v":"https://www.youtube.com/watch?v=nmvGGDL5G3g","cl":"","aka":"Broad Jump Stick","e":50},{"id":"x5","c":"ath","n":"Bodyweight Strength Circuit","t":8,"lv":2,"who":"solo","where":"inside","eq":"None","why":"Bodyweight strength. No weights needed at this age.","steps":["10 squats, 8 push-ups (knees okay), 20-second plank, 8 reverse lunges each, 10 glute bridges.","Rest 1 minute.","3 rounds."],"cues":["Perfect form beats fast","Full range"],"game":"Add one rep to something each week.","v":"","cl":"","aka":"Kid Strength Circuit","nov":1},{"id":"x6","c":"ath","n":"Jump Rope","t":5,"lv":1,"who":"solo","where":"yard","eq":"Jump rope","why":"Quick feet, rhythm and conditioning in one.","steps":["30 seconds on, 30 seconds off.","6 rounds.","Try single-leg and side-to-side once it's easy."],"cues":["Small jumps","Wrists turn the rope"],"game":"Most jumps without a miss.","v":"","cl":"","nov":1},{"id":"x7","c":"ath","n":"One-Leg Balance Reaches","t":4,"lv":1,"who":"solo","where":"inside","eq":"None","why":"Balance is the base of pitching, hitting and fielding.","steps":["Stand on one leg.","Reach the other foot forward, sideways, and back without touching down.","5 trips each leg."],"cues":["Quiet upper body","Knee soft"],"game":"Close your eyes for the last trip.","v":"https://www.youtube.com/watch?v=-DMwwqn5gpk","cl":"","aka":"Balance and Reach","s":10,"e":70},{"id":"x8","c":"ath","n":"One-Bounce Wall Catches","t":5,"lv":2,"who":"solo","where":"yard","eq":"Reaction ball or tennis ball, wall","why":"Hand-eye coordination.","steps":["Drop or bounce a ball off a wall.","Catch it after one bounce with your bare hand.","20 catches each hand."],"cues":["Athletic stance","Eyes track the ball"],"game":"Catch 10 in a row with your glove hand.","v":"https://www.youtube.com/watch?v=rkrPA2bGqAU","cl":"","aka":"Reaction Ball","s":218,"e":252},{"id":"q1","c":"iq","n":"Know the Play Before the Pitch","t":3,"lv":1,"who":"solo","where":"inside","eq":"None","why":"The best players know what they'll do before the ball is hit.","steps":["Before every pitch ask: How many outs? Where are the runners? Where's my throw if it comes to me?","Practice it while watching a game on TV for one full inning.","Say your answer out loud before each pitch."],"cues":["Outs, runners, where's my play"],"game":"Watch with a parent and see who calls the play right more often.","v":"https://www.youtube.com/watch?v=93vYbUqdIeM","cl":"","aka":"Before-Pitch Checklist","e":37},{"id":"q2","c":"iq","n":"Reset After a Mistake","t":3,"lv":1,"who":"solo","where":"inside","eq":"None","why":"What to do after a mistake. Everyone makes them.","steps":["Take one slow breath in through your nose, out through your mouth.","Pick a spot (the foul pole, your glove lace) and look at it.","Say your reset word: 'Next pitch.'"],"cues":["One breath","One spot","Next pitch"],"game":"","v":"https://www.youtube.com/watch?v=gBEwCNxNq0c","cl":"","aka":"Breathe and Reset","s":33,"e":93},{"id":"q3","c":"iq","n":"Watch Your Position on TV","t":15,"lv":1,"who":"solo","where":"inside","eq":"A game on TV","why":"Learn by watching one position.","steps":["Pick the player at your position.","Watch only them for a whole inning: where do they stand, where do they move on each hit?","Write down one thing you noticed."],"cues":["Watch the feet","Watch before the pitch"],"game":"Tell your coach your one thing at practice.","v":"","cl":"","aka":"Watch an Inning","nov":1},{"id":"q4","c":"iq","n":"Keep Score of a Game","t":20,"lv":2,"who":"solo","where":"inside","eq":"Scorebook or paper","why":"Scoring a game teaches you the whole game.","steps":["Learn the position numbers 1–9.","Score one inning: K for strikeout, 6-3 for short to first, F8 for fly to center.","Check your book against the box score."],"cues":["Pitcher is 1, catcher is 2","Write small"],"game":"","v":"","cl":"","aka":"Keep the Book","nov":1},{"id":"q5","c":"iq","n":"Good Teammate Challenge","t":2,"lv":1,"who":"team","where":"field","eq":"None","why":"Great teams are loud for each other.","steps":["Today, say something good to three different teammates.","Be the first one to pick up a teammate after an error.","Carry something for the team without being asked."],"cues":["Name plus a specific thing","'Nice hustle, Player 4'"],"game":"","v":"https://www.youtube.com/watch?v=quIW6FAh6bM","cl":"","s":40,"e":100},{"id":"q6","c":"iq","n":"Learn the Team Signs","t":5,"lv":1,"who":"partner","where":"inside","eq":"None","why":"Missing a sign can cost a game.","steps":["Learn your team's indicator and signs for bunt, steal and take.","Have a parent give a sign sequence; say what's on.","10 sequences."],"cues":["Find the indicator first","Look the whole time"],"game":"Play the Signs game in the Play tab.","v":"https://www.youtube.com/watch?v=AZdj9jOelB8","cl":"","aka":"Signs Study","s":63,"e":123},{"id":"g1","c":"fun","n":"Wall Ball 500 (Fielding Game)","t":10,"lv":1,"who":"solo","where":"yard","eq":"Tennis ball, wall, glove","why":"Fielding reps disguised as a game.","steps":["Throw off the wall.","Catch in the air = 100, one hop = 50, grounder = 25. Drop = lose 50.","First to 500."],"cues":["Move your feet","Two hands"],"game":"","v":"https://www.youtube.com/watch?v=jBQar9CqGdA","cl":"","e":60},{"id":"g2","c":"fun","n":"Pickle (Rundown Game)","t":10,"lv":1,"who":"team","where":"yard","eq":"2 bases, ball, 3+ players","why":"Baserunning and rundown defense in the most fun way possible.","steps":["Two fielders, one or more runners between bases.","Runners try to reach a base safely.","Tagged out? Switch with the fielder."],"cues":["Fielders: ball up, run hard","Runners: watch the ball"],"game":"","v":"https://www.youtube.com/watch?v=0nFmjzUXT-8","cl":"","s":25,"e":85},{"id":"g3","c":"fun","n":"Pepper (Tap-Hitting Game)","t":8,"lv":2,"who":"team","where":"yard","eq":"Bat, ball, gloves, 3+ players","why":"Bat control and quick hands. An old-school classic.","steps":["Batter 15–20 feet from a line of fielders.","Fielders toss; batter taps soft grounders back.","Clean field = keep going. Batter rotates after 10."],"cues":["Half swings only","Fielders stay ready"],"game":"","v":"https://www.youtube.com/watch?v=mhgTeYZ8KEw","cl":"","e":37},{"id":"g4","c":"fun","n":"Home Run Derby (Wiffle)","t":15,"lv":1,"who":"team","where":"yard","eq":"Wiffle ball and bat","why":"Swing hard and have fun.","steps":["Set a home run line.","10 swings each. Over the line in the air = homer.","Most homers wins."],"cues":["Balanced finish even when you swing big"],"game":"","v":"","cl":"","nov":1},{"id":"g5","c":"fun","n":"Wall Strikeout (Pitch vs. Hit)","t":12,"lv":1,"who":"partner","where":"yard","eq":"Tennis ball, wall, chalk","why":"Pitching and hitting with two players.","steps":["Chalk a strike zone on a wall.","Pitch a tennis ball. Hits the box without a swing = strike.","3 outs per side."],"cues":["Easy effort. It's a game, not a bullpen."],"game":"","v":"","cl":"","aka":"Strikeout (Chalk Zone)","nov":1},{"id":"g6","c":"fun","n":"Knockout Grounders (Last One In)","t":8,"lv":1,"who":"team","where":"field","eq":"Balls, gloves","why":"Ground balls with something on the line.","steps":["Everyone in a line. Coach hits or rolls grounders.","Field it clean and throw it back: stay in.","Bobble: you're out and cheering. Last one standing wins."],"cues":["Stay low","Cheer loud when you're out"],"game":"","v":"","cl":"","nov":1},{"id":"g7","c":"fun","n":"Glove Flip Circle (Spell OUT)","t":8,"lv":2,"who":"team","where":"yard","eq":"Ball, gloves, 4+ players","why":"Glove flips and soft hands.","steps":["Stand in a circle.","Flip the ball to anyone using only your glove.","Bad flip or drop = a letter. Spell OUT and you're out."],"cues":["Soft hands","Glove only"],"game":"","v":"","cl":"","aka":"Flip"},{"id":"g8","c":"fun","n":"Target Tic-Tac-Toe","t":10,"lv":1,"who":"partner","where":"yard","eq":"Chalk or tape, tennis balls, wall","why":"Accuracy plus strategy.","steps":["Draw a big tic-tac-toe grid on a wall.","Take turns throwing. Hit a square to claim it.","Three in a row wins."],"cues":["Aim small, miss small"],"game":"","v":"https://www.youtube.com/watch?v=XrXId66hn6c","cl":"","s":50,"e":110},{"id":"g9","c":"fun","n":"Bucket Ball (Outfield Throw Game)","t":8,"lv":1,"who":"solo","where":"yard","eq":"Bucket, balls","why":"Outfield throws made fun.","steps":["Bucket on its side at home plate.","Throw from the outfield grass, one hop into the bucket.","In = 5, hits it = 2, close = 1."],"cues":["Low, one hop"],"game":"","v":"https://www.youtube.com/watch?v=K_XToSAhmhc","cl":"","s":42,"e":100},{"id":"g10","c":"fun","n":"Seated Quick-Toss Race","t":5,"lv":1,"who":"partner","where":"inside","eq":"Gloves, soft ball","why":"Quick transfers. Works in a living room with a soft ball.","steps":["Sit facing each other, 6 feet apart.","Toss back and forth as fast as you can, glove to hand to toss.","30 seconds. Count catches."],"cues":["Catch and take it out at the same time"],"game":"","v":"","cl":"","aka":"Glove Tap Race","nov":1},{"id":"t13","c":"throw","n":"Indoor Sock-Ball Target Throws","t":6,"lv":1,"who":"solo","where":"inside","eq":"Rolled-up sock, tape","why":"Throwing accuracy you can practice in any room without breaking anything.","steps":["Roll a pair of socks into a tight ball.","Tape a small square on a door or wall.","Throw from 10–12 feet with your real throwing motion. 20 throws."],"cues":["Four-seam grip, even on a sock","Same motion as a real throw","Aim small"],"game":"Square = 2, touching the tape = 1. Beat your score out of 20.","v":"https://www.youtube.com/watch?v=lOt4pnucO2g","cl":"","aka":"Sock Ball Target","s":28,"e":60},{"id":"o6","c":"of","n":"Indoor Sock-Ball Fly Balls","t":5,"lv":1,"who":"solo","where":"inside","eq":"Rolled-up sock, glove","why":"Catching while you move, with your glove turned every way an outfielder needs.","steps":["Toss a sock ball up in front of you, walk in and catch it.","Toss it behind you, drop step and catch it.","Catch 5 above your head, 5 at your belt, 5 backhand."],"cues":["Eyes on it all the way in","Two hands when you can","Quiet feet at the catch"],"game":"10 in a row without a drop, then try glove-only.","v":"https://www.youtube.com/watch?v=Lnfgd_ld_CM","cl":"","aka":"Sock Ball Fly Balls","s":67,"e":108},{"id":"f12","c":"field","n":"Bare Hand, Then Glove","t":6,"lv":1,"who":"partner","where":"inside","eq":"Soft ball or tennis ball, glove","why":"Big league infielders do this before they take a single ground ball. It teaches your hands to catch the ball the right way.","steps":["Kneel or get in a fielding stance. A helper rolls the ball from 6–8 feet.","No glove first: 5 straight on, 5 forehand, 5 backhand.","Put your glove on and repeat."],"cues":["Catch it out front","Fingers down","Bend your legs, not your waist"],"game":"Helper mixes them up without telling you where it's going.","v":"https://www.youtube.com/watch?v=7Rsrgp0p7n4","cl":"","e":60},{"id":"f13","c":"field","n":"Side-to-Side Pick-Up Grounders","t":5,"lv":2,"who":"partner","where":"inside","eq":"Soft ball","why":"Makes you use your legs to get down to the ball.","steps":["Stand about 6 feet from a helper.","They roll the ball a step to your left, then a step to your right.","Shuffle, field it out front, toss it back. 20 total."],"cues":["Stay low the whole time","Shuffle, don't cross your feet","Field it out front"],"game":"Count how many you can do in 30 seconds.","v":"","cl":"","aka":"Pick-Ups","nov":1},{"id":"f14","c":"field","n":"Glove Flips for Soft Hands","t":4,"lv":1,"who":"solo","where":"inside","eq":"Glove, ball","why":"Teaches your hand to open and close inside the glove.","steps":["Squeeze your glove closed and set the ball on the outside of the pocket.","Flip the ball up, open your glove and catch it.","Flip it again as soon as it touches. 30 flips."],"cues":["Stretch your hand wide to open","Soft catch","Quick flip"],"game":"Each touch is a point. How many before it hits the floor?","v":"","cl":"","nov":1},{"id":"f15","c":"field","n":"Ground Ball Footwork, No Ball","t":5,"lv":1,"who":"solo","where":"inside","eq":"Glove, a hallway","why":"Perfect footwork with no ball. Great for cold days.","steps":["Start in your ready position.","Right foot, left foot, field an imaginary ball out front.","Bring it to your belly, right foot, left foot, throwing position. 15 reps."],"cues":["Work through the ball","Glove out front","Finish sideways"],"game":"Do 5 with your eyes closed and freeze. Check your feet.","v":"https://www.youtube.com/watch?v=4UqDA8MfHes","cl":"","aka":"Shadow Ground Balls","s":82,"e":140},{"id":"f16","c":"field","n":"Glove-to-Hand Transfers","t":4,"lv":1,"who":"solo","where":"inside","eq":"Glove, ball","why":"A fast, clean transfer saves a full step on every throw.","steps":["Ball in your glove at your chest.","Turn the glove toward your throwing hand and take the ball out with a four-seam grip.","30 seconds. Count clean grips. 3 rounds."],"cues":["Take it out, don't flip it","Find the seams by feel","Hands meet in the middle"],"game":"Beat your count each round.","v":"https://www.youtube.com/watch?v=77r6mWAUecA","cl":"","aka":"Quick Transfers","s":133,"e":169},{"id":"h12","c":"hit","n":"Bunting Stance in a Mirror","t":5,"lv":1,"who":"solo","where":"inside","eq":"Bat (plastic is fine), mirror","why":"Bunting technique is all body position, so winter is the perfect time to learn it.","steps":["Stand in your normal stance in front of a mirror. Use a glove or shirt as home plate.","Have someone say 'pivot'. Pivot, slide your top hand up, bat out front.","Check the mirror: bat head above your hands, knees bent. 15 reps."],"cues":["Bat head above the hands","Bend your knees for low pitches","Bat out in front of the plate"],"game":"Add a ping-pong or wiffle ball in the basement once the positions are right.","v":"https://www.youtube.com/watch?v=EbQc9NDEpRk","cl":"","aka":"Mirror Bunting","s":75,"e":133},{"id":"h13","c":"hit","n":"Hip Turns (No Stride)","t":5,"lv":1,"who":"solo","where":"inside","eq":"Bat or broomstick","why":"Power comes from your hips. This stops lunging at the ball.","steps":["Athletic stance, bat across your chest or behind your back.","Without stepping, turn your back hip hard toward the pitcher.","Head stays still. 15 turns, then 10 real dry swings."],"cues":["Back hip fires","Head stays over your belt","No lunging forward"],"game":"Balance a cap on your head. It shouldn't fall off.","v":"https://www.youtube.com/watch?v=CPzMopFu95M","cl":"","aka":"Hip Turn Swings","s":19,"e":79},{"id":"h14","c":"hit","n":"Hit a Sock Ball With Your Hand","t":5,"lv":1,"who":"solo","where":"inside","eq":"Rolled-up sock","why":"Hand-eye coordination with zero equipment.","steps":["Toss a sock ball up with one hand.","Hit it with your other hand like it's a bat.","10 each hand."],"cues":["Watch it hit your hand","Short swing"],"game":"Call your shot: at the couch, at the pillow.","v":"https://www.youtube.com/watch?v=lOt4pnucO2g","cl":"","aka":"Sock Ball Hand Bat","s":58,"e":105},{"id":"p10","c":"pitch","n":"Pitching Motion in a Mirror","t":6,"lv":1,"who":"solo","where":"inside","eq":"Mirror, no ball","why":"See your own delivery. Slow reps build the same motion every time.","steps":["Go through your full delivery in slow motion in front of a mirror.","Check three things: tall at leg lift, stride straight at the mirror, finish over your front leg.","10 slow reps, 5 at game speed. No ball."],"cues":["Tall, then go","Stride to the target","Finish out front"],"game":"Record one on a phone and compare it to a big leaguer.","v":"","cl":"","aka":"Mirror Delivery","nov":1},{"id":"p11","c":"pitch","n":"Pitch Grips and Backspin Flips","t":5,"lv":1,"who":"solo","where":"inside","eq":"Baseball","why":"Know your grips by feel, and learn true backspin.","steps":["Find a four-seam grip, then a two-seam, then a changeup, without looking.","Lie on your back and flick the ball straight up with a four-seam grip.","Watch the seams: you want clean backspin. 20 flips."],"cues":["Fingers behind the ball","Make the ball spin straight backward","Catch it at the same spot"],"game":"How many in a row land back in your hand without moving your elbow?","v":"https://www.youtube.com/watch?v=t82tKENmxig","cl":"","aka":"Grip School and Spin Flips","s":63,"e":115},{"id":"c5","c":"catch","n":"Catcher: Bare-Hand Catching","t":5,"lv":1,"who":"partner","where":"inside","eq":"Tennis or sock balls","why":"Teaches a catcher's hand to stay behind the ball and stick it.","steps":["Catcher's stance or both knees, no mitt.","Helper tosses soft balls from 8–10 feet.","Catch with your hand behind the ball and hold it still for a second. 20 catches."],"cues":["Hand behind the ball","Beat it to the spot","Stick it"],"game":"Then put the mitt on and do 20 more.","v":"","cl":"","aka":"Bare Hand Receiving","nov":1},{"id":"c6","c":"catch","n":"Catcher: Mitt-to-Hand Transfers","t":4,"lv":2,"who":"solo","where":"inside","eq":"Mitt, ball","why":"No throw happens until the ball is in your bare hand.","steps":["Ball in your mitt.","Turn the mitt so the pocket faces your bare hand and take the ball out with a four-seam grip.","Bring it to your ear. 20 reps."],"cues":["Take it out, don't flip it","Four-seam every time","Short and quick"],"game":"Time 10 in a row.","v":"https://www.youtube.com/watch?v=DWN8CnWH5ZI","cl":"","aka":"Catcher Transfers","e":30},{"id":"x9","c":"ath","n":"Wall Sit and Plank Challenge","t":5,"lv":1,"who":"solo","where":"inside","eq":"A wall","why":"Strong legs and a strong middle hold every baseball position.","steps":["Wall sit: back flat, knees at 90°. Hold 30 seconds.","Front plank 30 seconds, side plank 15 seconds each side.","Rest a minute. 3 rounds."],"cues":["Flat back","Breathe","Hips level"],"game":"Add 5 seconds each week.","v":"https://www.youtube.com/watch?v=q3gMS7-WVWM","cl":"","e":12},{"id":"x10","c":"ath","n":"Tape Ladder Quick Feet","t":5,"lv":1,"who":"solo","where":"inside","eq":"Painter's tape","why":"Quick feet without leaving the house.","steps":["Tape a ladder on the floor: 8 boxes.","One foot in each, two feet in each, sideways in-in-out-out.","3 trips of each."],"cues":["Stay on the balls of your feet","Eyes up","Arms pump"],"game":"Time a full set. Beat it tomorrow.","v":"https://www.youtube.com/watch?v=ZLNYijRpYUY","cl":"","aka":"Hallway Ladder","e":43},{"id":"x11","c":"ath","n":"Catch the Dropped Ball (Reaction)","t":4,"lv":1,"who":"partner","where":"inside","eq":"Tennis ball","why":"Reaction time and soft hands.","steps":["Helper holds a tennis ball at shoulder height.","You hold your hand a foot below it, palm down.","They drop it with no warning. Catch it before it hits the floor. 10 each hand."],"cues":["Watch the ball, not the hand","Athletic stance"],"game":"Start your hand lower to make it harder.","v":"","cl":"","aka":"Drop Catch","nov":1},{"id":"q7","c":"iq","n":"Picture It First (Visualization)","t":5,"lv":1,"who":"solo","where":"inside","eq":"A quiet spot","why":"Big leaguers picture success before it happens.","steps":["Close your eyes. Picture walking to the plate at your home field.","See three at-bats: a line drive, a walk, and a hard hit after two strikes.","Then picture three plays at your position, made clean."],"cues":["See it in color","Feel the bat or glove","Always finish with a good one"],"game":"Do it the night before every game.","v":"","cl":"","aka":"See It First","nov":1},{"id":"q8","c":"iq","n":"Rule of the Week","t":8,"lv":1,"who":"solo","where":"inside","eq":"A parent","why":"Players who know the rules win extra bases and outs.","steps":["Pick one rule: infield fly, dropped third strike, obstruction, tagging up, or the balk.","Find out what it really says.","Teach it to a parent in one minute."],"cues":["If you can teach it, you know it"],"game":"Try to stump your coach at the next practice.","v":"https://www.youtube.com/watch?v=iphFBx_Ejk4","cl":"","s":15,"e":75},{"id":"v1","c":"arm","n":"Standing Twists and Side Reaches","t":4,"lv":1,"who":"solo","where":"inside","eq":"Floor space","why":"Loosens your back and sides before you throw.","steps":["Feet wide. Rotate side to side as far as you can, feet planted.","Reach up and over to the side to stretch your lat, each way.","Lean over and draw circles with your upper body (stir the pot), both directions."],"cues":["Feet stay planted","Go to your full range"],"game":"","v":"https://www.youtube.com/watch?v=Ge6Dm0HcE0Y","cl":"","e":58},{"id":"v2","c":"arm","n":"Low Lunge: Hips to Heel","t":4,"lv":1,"who":"solo","where":"inside","eq":"Floor space","why":"Opens your hip flexor and deep hamstring.","steps":["Step into a long lunge, hands on the ground.","Press your hips down toward your front heel, then back.","Slow reps, then switch legs."],"cues":["Hips sink down","Breathe"],"game":"","v":"https://www.youtube.com/watch?v=Ge6Dm0HcE0Y","cl":"","s":160,"e":218},{"id":"v3","c":"arm","n":"Lunge Reach and Rotate","t":4,"lv":1,"who":"solo","where":"inside","eq":"Floor space","why":"Gets your upper back turning, which saves your arm.","steps":["From a lunge, put one hand by your ear.","Reach down to the ground, then rotate and point your elbow to the sky.","5 each side, then switch."],"cues":["Rotate from your upper back","Follow your hand with your eyes"],"game":"","v":"https://www.youtube.com/watch?v=Ge6Dm0HcE0Y","cl":"","s":300,"e":358},{"id":"v4","c":"arm","n":"Hip Circles on Hands and Knees","t":4,"lv":1,"who":"solo","where":"inside","eq":"Floor space","why":"Free hips move better when you throw and run.","steps":["On hands and knees. Lift one knee out to the side.","Rotate it back, then kick the heel up toward the sky and bring it back down.","5 each way, each leg."],"cues":["Core tight","Don't arch your back"],"game":"","v":"https://www.youtube.com/watch?v=Ge6Dm0HcE0Y","cl":"","s":400,"e":458},{"id":"v5","c":"arm","n":"Band Pull-Apart Y","t":3,"lv":1,"who":"solo","where":"inside","eq":"Light band (green Theraband for 12U)","why":"Strengthens the back of the shoulder.","steps":["Hold the band with arms up in a Y.","Pull the band apart and slowly come back.","2 x 10."],"cues":["Slow on the way back","Shoulders down"],"game":"","v":"https://www.youtube.com/watch?v=awSMT7PlZ5A","cl":"","s":121,"e":157},{"id":"v6","c":"arm","n":"Band No-Money","t":3,"lv":1,"who":"solo","where":"inside","eq":"Light band","why":"Builds the small rotator cuff muscles.","steps":["Elbows bent and tucked at your sides, palms up, band in both hands.","Rotate your hands out to the sides, keep elbows glued in.","2 x 10."],"cues":["Elbows stay on your ribs","Squeeze shoulder blades"],"game":"","v":"https://www.youtube.com/watch?v=awSMT7PlZ5A","cl":"","s":157,"e":196},{"id":"v7","c":"arm","n":"Band External Rotation","t":3,"lv":1,"who":"solo","where":"inside","eq":"Light band, anchor","why":"Keeps the back of your shoulder strong for throwing.","steps":["Anchor the band at elbow height. Elbow at your side, bent to 90°.","Rotate your hand out away from your body, then slowly back.","2 x 10 each arm."],"cues":["Elbow stays at your side","Control it back in"],"game":"","v":"https://www.youtube.com/watch?v=awSMT7PlZ5A","cl":"","s":196,"e":246},{"id":"v8","c":"arm","n":"Band Sword Pull","t":3,"lv":2,"who":"solo","where":"inside","eq":"Light band, anchor","why":"Works the shoulder in a throwing-like pattern.","steps":["Anchor the band low. Grab it across your body by the opposite hip.","Pull up and out like drawing a sword, ending with your arm up and out.","2 x 8 each arm."],"cues":["Smooth, not jerky","Finish tall"],"game":"","v":"https://www.youtube.com/watch?v=awSMT7PlZ5A","cl":"","s":246,"e":297},{"id":"v9","c":"arm","n":"Band Internal Rotation at 90","t":3,"lv":2,"who":"solo","where":"inside","eq":"Light band, anchor","why":"Strength through the throwing position.","steps":["Anchor the band behind you. Elbow up at shoulder height, bent to 90°.","Rotate your hand forward and down, then slowly back up.","2 x 8, light band only."],"cues":["Elbow stays level","Slow on the way back"],"game":"","v":"https://www.youtube.com/watch?v=yrgUzW0UK40","cl":"","s":180,"e":225},{"id":"v10","c":"arm","n":"Cat-Cow Stretch","t":2,"lv":1,"who":"solo","where":"inside","eq":"Floor space","why":"Moves your spine after you throw.","steps":["On hands and knees.","Round your back up to the ceiling, then let your belly drop and look up.","Slow, 10 times."],"cues":["Breathe in and out with each move"],"game":"","v":"https://www.youtube.com/watch?v=EunHAooYktE","cl":"","s":181,"e":211},{"id":"v11","c":"arm","n":"Walk-Out to Overhead Reach","t":3,"lv":1,"who":"solo","where":"inside","eq":"Floor space","why":"Opens the shoulders and gets the whole body moving.","steps":["Lie face down. Walk your hands out and reach long overhead.","Hold, then walk back in.","5 reps."],"cues":["Long reach","Slow and controlled"],"game":"","v":"https://www.youtube.com/watch?v=EunHAooYktE","cl":"","s":49,"e":98},{"id":"v12","c":"arm","n":"Three-Way Cone Reach","t":3,"lv":1,"who":"solo","where":"inside","eq":"3 cones or cups","why":"Balance and leg control on one leg.","steps":["Stand on one leg with 3 cones in front, left and right.","Reach down and touch each cone without putting your other foot down.","3 rounds each leg."],"cues":["Knee over toes","Hips level"],"game":"","v":"https://www.youtube.com/watch?v=EunHAooYktE","cl":"","s":98,"e":158},{"id":"v13","c":"throw","n":"Wrist Flick Catch","t":3,"lv":1,"who":"partner","where":"inside","eq":"Baseball, glove","why":"Warms up the arm and teaches four-seam spin.","steps":["Stand 10–12 feet apart with a four-seam grip.","Elbow about even with your shoulder. Flick your wrist to throw.","Catch it out in front. 10–15 throws."],"cues":["Four-seam spin","Catch out front","Accurate from the first throw"],"game":"","v":"https://www.youtube.com/watch?v=77r6mWAUecA","cl":"","e":33},{"id":"v14","c":"throw","n":"Rotation Throws, Feet Planted","t":3,"lv":1,"who":"partner","where":"yard","eq":"Baseball, glove","why":"Teaches your upper body to turn and throw.","steps":["Face your partner, all ten toes pointed at them.","Keep your feet on the ground. Rotate from the waist up and throw.","10 throws."],"cues":["Feet stay down","Throw it through your partner's chest"],"game":"","v":"https://www.youtube.com/watch?v=77r6mWAUecA","cl":"","s":33,"e":66},{"id":"v15","c":"throw","n":"Shuffle and Throw","t":3,"lv":1,"who":"partner","where":"yard","eq":"Baseball, glove","why":"Adds momentum so your throw has carry.","steps":["Catch the ball, turn sideways.","Shuffle your feet toward your partner and throw through them.","10 throws."],"cues":["Shuffle, don't cross over","Throw through your partner"],"game":"","v":"https://www.youtube.com/watch?v=77r6mWAUecA","cl":"","s":100,"e":133},{"id":"v16","c":"throw","n":"Throw Like Your Position","t":5,"lv":1,"who":"partner","where":"yard","eq":"Baseball, glove","why":"Makes catch play look like the throws you make in games.","steps":["Start with the ball in your glove every time so you practice your transfer.","Infielders: field, shuffle and throw. Outfielders: catch behind the ball and throw. Catchers: from your stance, up and throw.","10 throws at your position."],"cues":["Ball starts in the glove","Feet move first"],"game":"","v":"https://www.youtube.com/watch?v=jy0UwFdlw9M","cl":"","s":180,"e":238},{"id":"v17","c":"of","n":"Outfield Pro Step","t":3,"lv":1,"who":"partner","where":"yard","eq":"Baseball, glove","why":"Gets your feet set to throw after a ground ball.","steps":["Field the ball outside your glove-side foot, nice and low.","Step your throwing-side foot behind your glove-side foot to get turned.","Throw. 8 reps."],"cues":["Back foot goes behind","Stay low"],"game":"","v":"https://www.youtube.com/watch?v=g7Oa9ntktVw","cl":"","e":58},{"id":"v18","c":"throw","n":"Relay Catch: Turn to Your Glove Side","t":4,"lv":2,"who":"p3","where":"field","eq":"Baseballs, gloves","why":"Faster relays get runners out.","steps":["Go out as the relay. Move your feet so you catch the throw on your glove-side shoulder.","Turn to your glove side and throw to the target.","If the throw will bounce, go get it or back up. Don't take the in-between hop."],"cues":["Catch on the glove shoulder","Feet moving into the throw"],"game":"","v":"https://www.youtube.com/watch?v=Yle6R1-flA8","cl":"","e":60},{"id":"v19","c":"pitch","n":"Downhill Stride: Land in a Line","t":3,"lv":1,"who":"solo","where":"yard","eq":"A slope or low bench, chalk or tape","why":"Pitchers who land in a line throw strikes.","steps":["Stand on a slight slope (or a low bench) facing your target.","Do slow dry deliveries walking downhill toward the target.","Check that your stride foot lands on a straight line. 10 reps."],"cues":["Go toward the target","Land on the line"],"game":"","v":"https://www.youtube.com/watch?v=8ICgQDn9rh4","cl":"","s":150,"e":200},{"id":"v20","c":"pitch","n":"Towel Drill","t":4,"lv":1,"who":"partner","where":"inside","eq":"Hand towel, glove or bat to hold","why":"Great at-home pitching drill. No ball needed.","steps":["Hold a hand towel in your throwing hand like a ball.","A helper holds a glove or bat out in front as the target.","Do your delivery and snap the towel down onto the target. Finish with your chest over your front knee. Move back as you hit it."],"cues":["Reach out front","Finish forward, not up"],"game":"","v":"https://www.youtube.com/watch?v=8ICgQDn9rh4","cl":"","s":366,"e":426},{"id":"v21","c":"pitch","n":"Split-Stance Throws","t":3,"lv":2,"who":"partner","where":"yard","eq":"Baseball, glove","why":"Lets you feel the arm path without the whole delivery.","steps":["Start in a split stance, front side lined up with the target.","Feel the arm lead and the body follow. Easy effort.","10 throws."],"cues":["Front side at the target","Smooth, not hard"],"game":"","v":"https://www.youtube.com/watch?v=atOQzaC50ZM","cl":"","s":272,"e":305},{"id":"v22","c":"pitch","n":"Finish Drill","t":3,"lv":1,"who":"solo","where":"yard","eq":"Baseball, net or partner","why":"Builds a good finish so the arm can slow down safely.","steps":["Start already in your split stance, hips turned, arm up and ready.","Jog the arm through nice and slow and finish the pitch.","Hold your finish with your head still. 10 reps."],"cues":["Eyes on the catcher's mitt the whole way","Relaxed and free"],"game":"","v":"https://www.youtube.com/watch?v=McHb2hXrTrE","cl":"","s":40,"e":100},{"id":"v23","c":"pitch","n":"Scarecrow (Stride and Separate)","t":3,"lv":2,"who":"solo","where":"yard","eq":"Baseball","why":"Teaches the power position before the throw.","steps":["Get in your stride with your arms up in the power position.","Put a little weight in your back leg. Rock up, back, tap. Do it twice.","On the third one, throw."],"cues":["Stride straight at the target","Eyes on the target"],"game":"","v":"https://www.youtube.com/watch?v=McHb2hXrTrE","cl":"","s":120,"e":180},{"id":"v24","c":"pitch","n":"Low Balance Drive","t":3,"lv":2,"who":"solo","where":"yard","eq":"Baseball","why":"Connects the leg lift to the stride.","steps":["Start at low balance: knee coming down, hands breaking, thumbs in.","Weight on the back leg, then stride and separate.","Throw and hold your balance at the finish. 8 reps."],"cues":["Weight back first","Hold the finish"],"game":"","v":"https://www.youtube.com/watch?v=McHb2hXrTrE","cl":"","s":212,"e":272},{"id":"v25","c":"pitch","n":"Load and Go","t":3,"lv":2,"who":"solo","where":"yard","eq":"Baseball","why":"Puts the whole delivery together.","steps":["Start at low balance.","Pump up and down three times, then go into your full delivery.","Hold your balance at the end. 8 reps."],"cues":["Rhythm","Hold your finish"],"game":"","v":"https://www.youtube.com/watch?v=McHb2hXrTrE","cl":"","s":284,"e":344},{"id":"v26","c":"pitch","n":"Leg Lift Drill","t":3,"lv":1,"who":"solo","where":"inside","eq":"None","why":"Builds a controlled leg lift you can repeat.","steps":["Start on the rubber (or a line).","Lift your knee, let the lead foot go back, then come forward through a dry delivery.","10 slow reps, then 5 at game speed."],"cues":["Control the lift","Drive to the target"],"game":"","v":"https://www.youtube.com/watch?v=5KtXcDkQwMg","cl":"","s":131,"e":191},{"id":"v27","c":"pitch","n":"Wall Drill (Stay Closed)","t":3,"lv":2,"who":"solo","where":"inside","eq":"A wall","why":"Stops flying open so you stay on a straight line.","steps":["Stand close to a wall on your glove side, set up like you're on the mound.","Go slowly through your delivery. If you open up or over-rotate, you'll touch the wall.","10 slow reps."],"cues":["Throw straight down the line to the target","Stay on a straight line"],"game":"","v":"https://www.youtube.com/watch?v=5KtXcDkQwMg","cl":"","s":338,"e":398},{"id":"v28","c":"hit","n":"One-Hand Broomstick Swings","t":3,"lv":1,"who":"solo","where":"inside","eq":"Broomstick or bat","why":"Teaches each hand its job.","steps":["Top hand only: load and swing through.","Bottom hand only: palm down, swing and extend.","8 each."],"cues":["Short to the ball","Finish your extension"],"game":"","v":"https://www.youtube.com/watch?v=_yz-Jq8Tbmc","cl":"","s":116,"e":149},{"id":"v29","c":"hit","n":"Top-Hand Tee Swings","t":4,"lv":2,"who":"solo","where":"yard","eq":"Tee, balls, short bat","why":"Builds a strong top hand through contact.","steps":["Top hand on the bat, other hand on your chest.","Swing so your top hand is palm up at contact with a little bend in your elbow.","Extend through, then let the hand turn over. 8 swings."],"cues":["Palm up at contact","Contact out front"],"game":"","v":"https://www.youtube.com/watch?v=ZdxaI4fd95c","cl":"","s":150,"e":210},{"id":"v30","c":"hit","n":"Catch It With the Bat","t":3,"lv":1,"who":"partner","where":"yard","eq":"Bat, soft balls","why":"The secret to a good bunt.","steps":["Square or pivot to bunt, bat out front, top of the bat above your hands.","Top hand pinches the barrel from behind so your fingers stay safe.","On a low pitch bend your knees, don't drop the bat. Catch the ball with the bat like a glove."],"cues":["Soft hands","Bend your knees, not the bat"],"game":"","v":"https://www.youtube.com/watch?v=EbQc9NDEpRk","cl":"","s":230,"e":290},{"id":"v31","c":"hit","n":"Ball or Strike? (Aggressive Takes)","t":5,"lv":1,"who":"partner","where":"yard","eq":"Helper, balls","why":"Good hitters swing at strikes. This trains your eyes.","steps":["Get in your stance and load on every pitch, but don't swing.","Call “ball” or “strike” (or “yes”/“no”) before the ball gets to you.","Helper mixes balls and strikes. Try to call it earlier each time."],"cues":["Load every time","Call it early"],"game":"","v":"https://www.youtube.com/watch?v=2uEoyrtBJGo","cl":"","s":112,"e":172},{"id":"v32","c":"hit","n":"Hips Turn, Chest Waits","t":3,"lv":2,"who":"solo","where":"inside","eq":"Broomstick or PVC pipe","why":"Separation between hips and shoulders makes power.","steps":["Hold a stick and get into your launch position.","Start turning your hips while your chest stays where it is.","Then finish the full swing: knee, hip, torso. 10 reps."],"cues":["Drive the ball back up the middle","Keep your tilt"],"game":"","v":"https://www.youtube.com/watch?v=CPzMopFu95M","cl":"","s":102,"e":160},{"id":"v33","c":"field","n":"Cone Circle, Then Field","t":4,"lv":1,"who":"partner","where":"yard","eq":"A cone, balls","why":"Keeps your feet moving into every ground ball.","steps":["Take quick choppy steps counterclockwise around a cone.","When you reach the back of the cone, a partner rolls the ball.","Keep moving, right-left, field it with your momentum going toward first base."],"cues":["Feet never stop","Field it inside your left foot"],"game":"","v":"https://www.youtube.com/watch?v=Uj5lw17XvuI","cl":"","s":55,"e":110},{"id":"v34","c":"field","n":"Line Drill: Get Off the Line","t":4,"lv":1,"who":"solo","where":"field","eq":"A foul line or tape, balls","why":"Seeing the ball from an angle makes the hops easier.","steps":["Line up balls about three steps apart on a line.","For each ball: step off the line, come around the ball and field it.","Then come back through and move to the next one."],"cues":["Get out of the line of fire","Work back through the ball"],"game":"","v":"https://www.youtube.com/watch?v=Uj5lw17XvuI","cl":"","s":165,"e":220},{"id":"v35","c":"field","n":"Rolled Ball on the Line","t":4,"lv":2,"who":"partner","where":"field","eq":"A foul line, balls","why":"The game-speed version of the line drill.","steps":["Stand on a line. A partner rolls the ball straight down the line at you.","Step off the line, get around the ball and field it.","Fire your feet back through toward your target. 10 reps."],"cues":["Off the line, then back through","Quick feet"],"game":"","v":"https://www.youtube.com/watch?v=Uj5lw17XvuI","cl":"","s":285,"e":335},{"id":"v36","c":"field","n":"Palm-Up Flip","t":4,"lv":2,"who":"p3","where":"yard","eq":"Balls, 3+ players","why":"The short underhand feed on a double play.","steps":["Three players in a triangle.","Catch the toss, point your front foot at your target and push off.","Flip it palm up, chest high, and follow it. Then the next player flips."],"cues":["Palm up, chest high","Follow your flip"],"game":"","v":"https://www.youtube.com/watch?v=Uj5lw17XvuI","cl":"","s":370,"e":424},{"id":"v37","c":"field","n":"Power Flip From Second","t":3,"lv":3,"who":"p3","where":"yard","eq":"Balls, 3+ players","why":"A firmer feed when the play takes you away from the bag.","steps":["Field moving away from the base.","Stay low, push off your left leg and dart your fingers at your partner's chest.","Quick and firm, not a lob. 8 reps."],"cues":["Fingers dart at the target","Stay low"],"game":"","v":"https://www.youtube.com/watch?v=Uj5lw17XvuI","cl":"","s":457,"e":498},{"id":"v38","c":"field","n":"Second Base Pivot Throw","t":3,"lv":3,"who":"p3","where":"yard","eq":"Balls, 3+ players","why":"Turning a double play from second base.","steps":["Catch the feed and roll into your right hip.","Throw so the ball goes uphill to your partner's chest.","Don't spike it down. 8 reps."],"cues":["Roll into the right hip","Ball goes uphill"],"game":"","v":"https://www.youtube.com/watch?v=Uj5lw17XvuI","cl":"","s":498,"e":548},{"id":"v39","c":"field","n":"Bad Hop Drill","t":4,"lv":2,"who":"partner","where":"yard","eq":"A PVC pipe or cones, soft balls","why":"Prepares you for the ball that takes a crazy bounce.","steps":["Lay a PVC pipe or cones on the ground. Use soft balls.","A partner rolls balls so some hit the pipe and pop up and some don't.","Attack every ball and react to the hop."],"cues":["Soft balls only","Attack, don't wait"],"game":"","v":"https://www.youtube.com/watch?v=Uj5lw17XvuI","cl":"","s":737,"e":790},{"id":"v40","c":"field","n":"Drop-and-Pick Short Hops","t":3,"lv":1,"who":"solo","where":"inside","eq":"Soft ball or tennis ball, glove","why":"Lots of short hops with no partner.","steps":["Drop the ball in front of you.","Pick it right after it hits the ground, on the short hop.","Forehand, then backhand. Short, not swiping."],"cues":["Get the glove down to the bounce","Glove out front"],"game":"","v":"https://www.youtube.com/watch?v=_yz-Jq8Tbmc","cl":"","s":40,"e":90},{"id":"v41","c":"field","n":"Right-Left, Tap-Tap","t":3,"lv":1,"who":"solo","where":"inside","eq":"Glove","why":"Builds the footwork into every ground ball.","steps":["Step right, left into your fielding position.","Flat back, tap your glove to the ground twice.","Repeat 10, then add right-left and a fake throw."],"cues":["Flat back","Glove out front"],"game":"","v":"https://www.youtube.com/watch?v=Yc7gxp7FNDA","cl":"","s":25,"e":85},{"id":"v42","c":"field","n":"Round the Ball (Cones)","t":4,"lv":1,"who":"solo","where":"yard","eq":"3 cones, ball","why":"Fielding with momentum toward first base.","steps":["Set three cones with a ball past them, or have a partner roll it.","Take your ready step, round the ball around the cones.","Right-left, field it and finish toward first base."],"cues":["Round it, don't run straight at it","Momentum to first"],"game":"","v":"https://www.youtube.com/watch?v=Yc7gxp7FNDA","cl":"","s":120,"e":180},{"id":"v43","c":"field","n":"Ball Handling Like a Basketball Player","t":3,"lv":1,"who":"solo","where":"inside","eq":"Ball, glove","why":"More touches make you smoother with the ball.","steps":["Move the ball from hand to glove around your body.","Pass it under your legs and behind your back.","Make up your own moves. 2 minutes."],"cues":["Lots of touches","Have fun with it"],"game":"","v":"https://www.youtube.com/watch?v=Yc7gxp7FNDA","cl":"","s":195,"e":255},{"id":"v44","c":"field","n":"Rundown Footwork (No Runner)","t":5,"lv":2,"who":"p4","where":"field","eq":"2 bases, balls","why":"Clean rundown footwork before adding a runner.","steps":["Lines at two bases. Sprint toward the other base with the ball up.","Your partner calls “ball.” Give a short wrist flick toss.","Keep running outside the lane to the end of the line."],"cues":["Ball up, no pump fakes","Toss on the call"],"game":"","v":"https://www.youtube.com/watch?v=cV8Ivq0XcJA","cl":"","s":47,"e":107},{"id":"v45","c":"field","n":"Bare-Hand Short Hop Picks","t":3,"lv":1,"who":"partner","where":"inside","eq":"Tennis or soft balls","why":"Teaches soft, quick hands.","steps":["Wide stance, no glove, fingers pointing down.","A partner tosses short hops to you.","Pick back through the ball. Then do it with two hands."],"cues":["Fingers down, don't scoop","Through the ball"],"game":"","v":"https://www.youtube.com/watch?v=zBfiZZ9G9zg","cl":"","s":40,"e":100},{"id":"v46","c":"field","n":"Ozzie Drill (Quick Rolls on Knees)","t":3,"lv":2,"who":"partner","where":"inside","eq":"Soft balls, a pad for your knees","why":"Fast hands on ground balls.","steps":["Kneel on a pad, hands out front.","A partner rolls balls quickly to your left and right.","Field each one and flip it back."],"cues":["Meet the ball out in front","Stay low"],"game":"","v":"https://www.youtube.com/watch?v=zBfiZZ9G9zg","cl":"","s":105,"e":165},{"id":"v47","c":"field","n":"Feed the Chickens","t":3,"lv":2,"who":"partner","where":"yard","eq":"Soft balls","why":"Reactions on forehand and backhand.","steps":["A partner walks toward you, tossing short hops to your forehand and backhand.","Field each one and toss it back as you backpedal.","Keep going for 30 seconds."],"cues":["Soft balls","Quick hands"],"game":"","v":"https://www.youtube.com/watch?v=zBfiZZ9G9zg","cl":"","s":295,"e":340},{"id":"v48","c":"field","n":"Wall Bounce Short Hops (Bare Hand)","t":3,"lv":1,"who":"solo","where":"inside","eq":"Tennis ball, wall","why":"Hundreds of short hops by yourself.","steps":["No glove. Throw a tennis ball low against a wall.","Pick it right after it hits the ground.","Forehand, then backhand."],"cues":["Catch the short hop","Short hands"],"game":"","v":"https://www.youtube.com/watch?v=xLDvG-GqazY","cl":"","s":75,"e":110},{"id":"v49","c":"field","n":"Pancake Glove Short Hops","t":3,"lv":2,"who":"solo","where":"inside","eq":"Flat training glove or your glove, tennis ball","why":"Forces two hands and soft catches.","steps":["Use a flat (pancake) glove or your regular glove.","Wait for the short hop and come through the ball.","Two hands every time. 20 reps."],"cues":["Two hands","Come through the ball"],"game":"","v":"https://www.youtube.com/watch?v=xLDvG-GqazY","cl":"","s":100,"e":155},{"id":"v50","c":"field","n":"Cone Box: Field to Throw","t":3,"lv":1,"who":"solo","where":"inside","eq":"4 cones","why":"Smooth change from fielding to throwing.","steps":["Set 4 cones in a box a little wider than your shoulders.","Get in fielding position, then move to throwing position using the box.","Reset and go around the box."],"cues":["Ball to your middle","Right foot to left foot"],"game":"","v":"https://www.youtube.com/watch?v=4UqDA8MfHes","cl":"","s":199,"e":237},{"id":"v51","c":"field","n":"Cone Weave Shuffle","t":3,"lv":1,"who":"solo","where":"yard","eq":"Cones","why":"Quick feet while staying low.","steps":["Make a line of cones.","Shuffle in and out of them staying low and athletic.","Go as fast as you can with good footwork."],"cues":["Stay low","Quick feet"],"game":"","v":"https://www.youtube.com/watch?v=4UqDA8MfHes","cl":"","s":276,"e":306},{"id":"v52","c":"field","n":"Zigzag Pick-Ups","t":4,"lv":2,"who":"solo","where":"yard","eq":"Cones, 2+ balls","why":"Rounding the ball, fielding and getting into the throw.","steps":["Two zigzag lines of cones with a ball inside each cone.","Come around the first cone, right-left, pick it up, get to throwing position.","Drop it and go around the next cone."],"cues":["Round the ball","Right-left, field"],"game":"","v":"https://www.youtube.com/watch?v=4UqDA8MfHes","cl":"","s":306,"e":360},{"id":"v53","c":"field","n":"Short Hop or High Hop Box","t":4,"lv":2,"who":"partner","where":"yard","eq":"4 cones, balls","why":"Choose the good hop instead of the in-between hop.","steps":["Stand in the middle of a box of cones.","Short hop: step toward the cone with your left foot and pick it.","High hop: drop step to make room and catch it on the high hop."],"cues":["Eyes behind the glove","Avoid the in-between hop"],"game":"","v":"https://www.youtube.com/watch?v=4UqDA8MfHes","cl":"","s":360,"e":420},{"id":"v54","c":"of","n":"Fly Ball Bucket Drill","t":4,"lv":1,"who":"partner","where":"yard","eq":"Empty bucket, balls","why":"Teaches you to judge where a fly ball will land.","steps":["A helper tosses a high fly ball.","Run to where you think it will land and set the bucket down there.","Ball lands in or next to the bucket = a point."],"cues":["Read it off the hand","Run, don't drift"],"game":"","v":"https://www.youtube.com/watch?v=dHE3kxsZQsc","cl":"","s":150,"e":210},{"id":"v55","c":"of","n":"Frisbee Fly Balls","t":3,"lv":1,"who":"partner","where":"yard","eq":"Frisbee or flying disc","why":"Fun tracking and feet-moving practice.","steps":["A helper throws a frisbee.","Track it and catch it on the run.","Keep your feet moving the whole time."],"cues":["Eyes on it","Feet never stop"],"game":"","v":"https://www.youtube.com/watch?v=dHE3kxsZQsc","cl":"","s":75,"e":135},{"id":"v56","c":"of","n":"Hop, Drop Step, Go","t":4,"lv":2,"who":"partner","where":"yard","eq":"A low step, balls","why":"A quick first step on balls over your head.","steps":["Hop off a low step.","As you land, a helper tosses to your left or right.","Drop step or crossover and catch it."],"cues":["First step back","No hesitation"],"game":"","v":"https://www.youtube.com/watch?v=dHE3kxsZQsc","cl":"","s":240,"e":300},{"id":"v57","c":"of","n":"Ball on the Brim","t":3,"lv":1,"who":"partner","where":"yard","eq":"Soft balls","why":"Teaches you to get all the way under a fly ball.","steps":["Soft balls only. A helper tosses it high.","Move your feet so the ball would land on the brim of your cap.","Catch it right there, above your eyes."],"cues":["Move your feet","Get under it, not beside it"],"game":"","v":"https://www.youtube.com/watch?v=Lnfgd_ld_CM","cl":"","s":160,"e":220},{"id":"v58","c":"catch","n":"Catcher: Angle Receiving","t":4,"lv":2,"who":"partner","where":"yard","eq":"Catcher's mitt, balls","why":"Catch pitches on the edges cleanly.","steps":["Your partner throws from an angle (the third-base side, then the first-base side).","Get the glove out to the pitch and catch it in the middle of the zone.","Turn the glove when the pitch is far out."],"cues":["Glove to the ball","Stick it"],"game":"","v":"https://www.youtube.com/watch?v=8EtK_1FoJgY","cl":"","s":73,"e":129},{"id":"v59","c":"catch","n":"Catcher: Stick It and Hear the Pop","t":3,"lv":1,"who":"partner","where":"yard","eq":"Catcher's mitt, balls","why":"A clean catch every time makes strikes look like strikes.","steps":["Good pre-pitch stance, glove relaxed.","Track the ball all the way into the glove.","Listen for the pop on every catch. No pop? Track it longer."],"cues":["Eyes all the way in","Quiet glove"],"game":"","v":"https://www.youtube.com/watch?v=8EtK_1FoJgY","cl":"","s":153,"e":198},{"id":"v60","c":"catch","n":"Catcher: Lateral Block Slides","t":3,"lv":2,"who":"solo","where":"yard","eq":"Catcher's gear","why":"Blocking balls to the side.","steps":["Get in your blocking position.","Slide to the side, get up, slide back.","Go back and forth 10 times."],"cues":["Push off, don't step","Stay square"],"game":"","v":"https://www.youtube.com/watch?v=Tjzv5anKEe0","cl":"","s":27,"e":53},{"id":"v61","c":"catch","n":"Catcher: Twist and Block","t":3,"lv":2,"who":"partner","where":"yard","eq":"Catcher's gear, soft balls","why":"Keeps the blocked ball in front of the plate.","steps":["Block toward the side.","Angle your shoulders so the ball bounces back toward home plate.","5 each side."],"cues":["Block the ball back toward the plate","Chin down"],"game":"","v":"https://www.youtube.com/watch?v=Tjzv5anKEe0","cl":"","s":53,"e":81},{"id":"v62","c":"catch","n":"Catcher Inchworms","t":3,"lv":1,"who":"solo","where":"inside","eq":"Catcher's gear optional","why":"Mobility for blocking and moving in your stance.","steps":["From a single-knee stance, inch your feet to one side.","Stay light on the shin guard and push the knee into the ground.","Go across and back."],"cues":["Light on the down knee","Stay low"],"game":"","v":"https://www.youtube.com/watch?v=Tjzv5anKEe0","cl":"","s":81,"e":128},{"id":"v63","c":"catch","n":"Catcher: Rapid Fire Side to Side","t":2,"lv":2,"who":"solo","where":"inside","eq":"None","why":"Quick feet in the single-knee stance.","steps":["Get in a single-knee stance.","Move side to side as fast as you can.","Count how many in 20 seconds."],"cues":["Fast and low","Stay balanced"],"game":"","v":"https://www.youtube.com/watch?v=Tjzv5anKEe0","cl":"","s":128,"e":148},{"id":"v64","c":"catch","n":"Catcher Footwork Standing Up","t":3,"lv":2,"who":"solo","where":"yard","eq":"Mitt","why":"Clean footwork before adding the throw.","steps":["Start in your receiving stance.","Move your feet into throwing position and get your elbows up.","No ball first, then with a ball. 10 reps."],"cues":["Elbows up","Quick feet"],"game":"","v":"https://www.youtube.com/watch?v=wd8eYHPhAJA","cl":"","s":89,"e":116},{"id":"v65","c":"catch","n":"Catcher: Shoulder Switch","t":3,"lv":2,"who":"partner","where":"yard","eq":"Mitt, ball","why":"A strong, short throw to second.","steps":["Play catch from your catcher's position.","Keep your back foot down and your weight centered. Switch shoulders as you throw.","Start every rep from the glove."],"cues":["Back foot stays down","Weight centered"],"game":"","v":"https://www.youtube.com/watch?v=wd8eYHPhAJA","cl":"","s":116,"e":173},{"id":"v66","c":"catch","n":"Catcher: Throw From Your Knees","t":3,"lv":3,"who":"partner","where":"yard","eq":"Mitt, ball","why":"For back-picks and quick throws when you can't stand.","steps":["Start on your knees in a receiving position.","Catch, transfer and throw to your partner from your knees.","10 throws."],"cues":["Quick transfer","Use your upper body"],"game":"","v":"https://www.youtube.com/watch?v=wd8eYHPhAJA","cl":"","s":173,"e":206},{"id":"v67","c":"catch","n":"Catcher: The Dunk","t":3,"lv":1,"who":"partner","where":"yard","eq":"Mitt, ball","why":"Bring the glove to the hand for a faster transfer.","steps":["Throwing-hand fingers up, ready by the mitt.","Catch and bring the glove to your hand, not your hand to the glove.","“Dunk” it in and come up to throw. 15 reps."],"cues":["Glove to hand","Quick and short"],"game":"","v":"https://www.youtube.com/watch?v=DWN8CnWH5ZI","cl":"","s":30,"e":58},{"id":"v68","c":"catch","n":"Catcher: Preset Shuffle and Throw","t":4,"lv":2,"who":"partner","where":"yard","eq":"Mitt, balls","why":"Puts transfer and footwork together toward second base.","steps":["Start turned slightly toward second base.","Catch, get the right foot down and throw.","Get moving as you catch."],"cues":["Right foot down","Move as you catch"],"game":"","v":"https://www.youtube.com/watch?v=DWN8CnWH5ZI","cl":"","s":105,"e":160},{"id":"v69","c":"run","n":"Pop-Up Slide With a Helper","t":4,"lv":2,"who":"partner","where":"yard","eq":"Grass or cardboard, long pants, a helper","why":"Learn to slide and pop right up.","steps":["A helper stands beside the base with a hand out.","Slide in with the bent-leg (figure 4) slide.","Grab the helper's hand and pop up. Later, do it without help."],"cues":["Feet first","Hands up"],"game":"","v":"https://www.youtube.com/watch?v=yRqqQGQt9FU","cl":"","s":160,"e":220},{"id":"v70","c":"ath","n":"Tennis Ball Juggling","t":3,"lv":2,"who":"solo","where":"inside","eq":"2–3 tennis balls","why":"Fast hands and eyes for every position.","steps":["Start juggling two tennis balls.","Try three when you're ready.","Count your catches and try to get 10 in a row."],"cues":["Toss to eye level","Relax your hands"],"game":"","v":"https://www.youtube.com/watch?v=rkrPA2bGqAU","cl":"","s":16,"e":68},{"id":"v71","c":"ath","n":"Over-the-Shoulder Catches","t":3,"lv":2,"who":"solo","where":"inside","eq":"Tennis ball","why":"Hand-eye and catching on the move.","steps":["Reach back and toss the ball over your shoulder from behind.","Catch it in front of you.","Do both sides. 10 each."],"cues":["Watch it come over","Soft hands"],"game":"","v":"https://www.youtube.com/watch?v=rkrPA2bGqAU","cl":"","s":319,"e":346},{"id":"v72","c":"ath","n":"Wall Push-Ups","t":2,"lv":1,"who":"solo","where":"inside","eq":"A wall","why":"Upper body strength at home.","steps":["Hands on the wall, up on your toes.","Lower your chest to the wall and push back.","Step back further to make it harder. 10–15 reps."],"cues":["Straight body","Slow down, fast up"],"game":"","v":"https://www.youtube.com/watch?v=q3gMS7-WVWM","cl":"","s":12,"e":24},{"id":"v73","c":"ath","n":"Wall Mountain Climbers","t":2,"lv":1,"who":"solo","where":"inside","eq":"A wall","why":"Core and leg drive.","steps":["Hands on the wall, lean in.","Drive one knee up, then the other, quickly.","20 seconds, rest, 3 rounds."],"cues":["Tight core","Quick knees"],"game":"","v":"https://www.youtube.com/watch?v=q3gMS7-WVWM","cl":"","s":24,"e":35},{"id":"v74","c":"ath","n":"Wall Bridge Lifts","t":2,"lv":1,"who":"solo","where":"inside","eq":"A wall","why":"Strong glutes help you run and throw.","steps":["Lie on your back, feet on the wall, knees bent.","Lift your hips off the floor and squeeze.","Hold 2 seconds, lower. 12 reps."],"cues":["Squeeze at the top","Don't arch"],"game":"","v":"https://www.youtube.com/watch?v=q3gMS7-WVWM","cl":"","s":60,"e":71},{"id":"v75","c":"iq","n":"Reset Action","t":2,"lv":1,"who":"solo","where":"inside","eq":"None","why":"A physical cue that tells your brain to move on.","steps":["Pick your reset action: wipe it off down your leg, step off, fix your hat.","After a mistake, take a deep breath and do your reset.","Then think only about the next pitch."],"cues":["Breathe, reset, next pitch"],"game":"","v":"https://www.youtube.com/watch?v=gBEwCNxNq0c","cl":"","s":133,"e":193},{"id":"v76","c":"iq","n":"Positive Self-Talk","t":2,"lv":1,"who":"solo","where":"inside","eq":"None","why":"What you say to yourself changes how you play.","steps":["Notice the negative thought (“don't walk him”).","Say what you WILL do instead (“hit the glove”).","The next pitch is the only one you control."],"cues":["Say what you will do"],"game":"","v":"https://www.youtube.com/watch?v=gBEwCNxNq0c","cl":"","s":199,"e":259}],"CATS":[{"k":"arm","n":"Arm Care","e":"💪","c":"#5CC8FF","d":"Cleary's warm-up and post-throw routine"},{"k":"throw","n":"Throwing","e":"🎯","c":"#FFC53D","d":"Catch play, accuracy, arm strength"},{"k":"pitch","n":"Pitching","e":"⚾","c":"#F0484B","d":"Balance, direction, strikes"},{"k":"hit","n":"Hitting","e":"🏏","c":"#FF8A3D","d":"Tee, toss and swing work"},{"k":"field","n":"Infield","e":"🧤","c":"#3DDC84","d":"Ground balls, footwork, feeds"},{"k":"of","n":"Outfield","e":"🌤️","c":"#7AA7FF","d":"Fly balls, routes, throws"},{"k":"catch","n":"Catcher","e":"🛡️","c":"#C792EA","d":"Receiving, blocking, throwing"},{"k":"run","n":"Baserunning","e":"💨","c":"#FF6FAE","d":"Turns, reads, leads"},{"k":"ath","n":"Athlete","e":"⚡","c":"#FFE66D","d":"Speed, strength, movement"},{"k":"iq","n":"Baseball IQ","e":"🧠","c":"#4EE1C1","d":"Mental game and know-how"},{"k":"fun","n":"Backyard Games","e":"🎉","c":"#FFB3C7","d":"Games that secretly make you better"}],"GOALS":[["acc","🎯","Throw more accurately",["t6","t13","t1","t2","t3","t12","t8","g8","p6","t5","v13","v14","v15"]],["arm","🚀","Build a stronger arm",["t9","t10","t5","a2","a3","a7","x4","x5","a9","a10","a8"]],["care","🛟","Keep my arm healthy",["a1","a9","a10","a11","a2","a3","a4","a5","v5","v6","v7","v8","v9","v10","v11"]],["gb","🧤","Field ground balls cleaner",["f1","f2","f3","f4","f15","f12","f13","f6","f5","f8","g1","g6","f16","v33","v34","v35","v41","v42","v50","v52","v53","v39","v40","v48","v49"]],["hands","✋","Quicker hands and transfers",["f16","f14","t7","f5","g10","g7","c6","x8","x11","g3","v45","v46","v47","v43","v67","v70","v71"]],["fly","🌤️","Catch fly balls",["o4","o6","o1","o2","f10","c4","v54","v55","v56","v57"]],["contact","👁️","Make more contact",["h2","h1","h6","h11","h3","h5","h8","h10","h14","h4","g3","v31","v28","v29"]],["power","💥","Hit the ball harder",["h13","h2","h4","h3","h7","x4","x5","g4","v32","v29"]],["bunt","🪶","Bunt",["h12","h9","v30"]],["strikes","⚾","Throw more strikes",["p6","t6","t13","p1","p4","p10","p3","p11","p7","g5","p8","v19","v20","v27","v21"]],["catcher","🛡️","Be a better catcher",["c1","c5","c2","c3","c6","c4","v58","v59","v60","v61","v62","v63","v64","v65","v66","v67","v68"]],["speed","⚡","Get faster",["x2","x6","x10","x3","r1","r6","x1","v51"]],["bases","💨","Run the bases smarter",["r1","r2","r3","r4","r5","r6","r7","g2","g_steal"]],["strong","🏋️","Get stronger and more athletic",["x5","x9","x4","x1","x7","x6","x10","v72","v73","v74"]],["iq","🧠","Know the game better",["q1","q3","q4","q6","q8","g_play","g_cut","g_score","g_pos","g_trivia"]],["mental","🧘","Confidence and bouncing back",["q2","q7","q5","v75","v76"]],["warm","🔥","Warm up the right way",["x1","a1","a2","a3","a4","a5","x7","a11","v1","v2","v3","v4","v12","v13"]],["timing","⏱️","Hit faster pitching",["h6","h7","h11","h10","h5","h8","g_swing","v31"]],["ofthrow","🏹","Outfield throws and hitting the cutoff",["o3","o5","t10","t9","g9","t12","t11","g_cut","v17","v18"]],["delivery","🌀","Smoother pitching motion",["p1","p4","p10","p3","p5","x7","a7","p11","v22","v23","v24","v25","v26","v19"]],["plays","🧩","Team plays: double plays, rundowns, covering",["f9","f11","f7","p9","f10","o2","g2","g_cut","v36","v37","v38","v44"]],["slide","🦵","Slide the right way",["r7","r6","r5","v69"]]],"GOAL_GRP":[["💪","Arm and throwing",["acc","arm","care","warm"]],["🧤","Defense",["gb","hands","fly","ofthrow","catcher","plays"]],["🏏","Hitting",["contact","power","timing","bunt"]],["⚾","Pitching",["strikes","delivery"]],["⚡","Speed and strength",["speed","bases","slide","strong"]],["🧠","Mind and smarts",["iq","mental"]]],"GOAL_TIP":{"acc":"Watch the glove arm. It should point at the target, then tuck in. The ball goes where the front shoulder points.","arm":"Arm strength comes from legs and good mechanics, not max-effort throws. Keep long toss easy and stop at any pain.","care":"Do arm care after throwing, not instead of rest. Sore muscles are normal. Pain in the elbow or shoulder means stop.","warm":"Body first, then short easy throws, then build distance. Never throw to warm up.","gb":"Roll the ball instead of throwing it at first. Look for feet wide, bottom down, glove out in front where they can see it.","hands":"Short, fast rounds beat long sets. Count catches in 30 seconds and try to beat it next time.","fly":"Use tennis balls so nobody gets hurt. Get under it early, then catch it above the eyes with two hands.","ofthrow":"Accuracy beats distance. A low throw that bounces once beats a high rainbow.","catcher":"Use soft or tennis balls for blocking. After each catch, the mitt should stay still for a second.","plays":"These need a few kids. Great for when teammates or neighbors come over.","contact":"Ask where the ball was when they hit it. Line drives up the middle are the goal, not home run swings.","power":"Power starts from the ground: legs and hips turn first, then the hands. Look for a balanced finish.","timing":"Toss from the side or from behind a screen. Mix up the speed once they hit it square.","bunt":"Bat out front, bat head above the hands. Bend the knees to go low instead of dropping the bat.","strikes":"Celebrate strikes, not speed. Keep pitch counts low: fastball and changeup only at 12U.","delivery":"Slow reps first. Film from the side and the front so they can see their own motion.","speed":"Full rest between sprints. Speed work is short and fast. Stop when they start slowing down.","bases":"Have them say the play out loud: how many outs, where the ball is, where they're going.","slide":"Start on wet grass or flattened cardboard in long pants. Feet first when going to a base: most 12U leagues don't allow head-first slides.","strong":"Bodyweight only at this age. Good form beats more reps.","iq":"Watch a game together and pause it: \"Where's the throw if it's hit to you?\"","mental":"Praise the effort and the reset, not the result. Ask what their reset word is."},"GOAL_CAT":{"acc":["throw"],"arm":["throw"],"care":["arm"],"warm":["arm","ath"],"gb":["field"],"hands":["field","catch"],"fly":["of"],"ofthrow":["of"],"catcher":["catch"],"plays":["field"],"contact":["hit"],"power":["hit"],"timing":["hit"],"bunt":["hit"],"strikes":["pitch"],"delivery":["pitch"],"speed":["ath","run"],"bases":["run"],"slide":["run"],"strong":["ath"],"iq":["iq"],"mental":["iq"]},"FW":[["inside","🛋️","Inside"],["yard","🏡","Backyard / driveway"],["field","🏟️","Field or park"]],"FWHO":[["solo","🙋","Just me"],["partner","🤝","Me + a helper"],["team","👥","3 or more"]],"FT":[10,20,30,45],"FIN0":{"goals":[],"where":"yard","who":"","time":20,"lv":0,"short":false,"vid":false,"nogear":false,"games":true,"open":true,"more":false},"POST":["a9","a10","a11"],"PATHS":[["gb","🧤","Ground Balls",["f1","v41","f12","v40","f4","f5","v42","f6","v53","f8"]],["throw","🎯","Throwing",["t1","v13","t2","v14","t3","v15","t5","t8","t10"]],["pitch","⚾","Pitching Delivery",["p1","v26","v22","p4","v23","v24","v25","v27","p5"]],["hit","🏏","Hitting",["h1","h13","h2","h4","v29","h5","h8","h3","h6"]],["catch","🛡️","Catcher",["c1","v59","c6","v67","c2","v60","c3","v65","v68"]],["of","🌤️","Outfield",["o6","o1","v57","o4","v54","v56","o3"]],["run","💨","Base Running",["r1","r2","r7","v69","r6"]],["bunt","🪶","Bunting",["h12","v30","h9"]],["mind","🧠","Mental Game",["q2","v75","v76"]]],"WHO_L":{"solo":"By myself","partner":"2+ people","p3":"3+ people","p4":"4+ people","p5":"5+ people","p6":"6+ people","p7":"7+ people","p8":"8+ people","p9":"9+ people","p10":"10+ people","team":"Full team"},"WHERE_L":{"inside":"Indoors","driveway":"Driveway","yard":"Backyard","field":"Field"},"FILMS":[["v1","The Bug Game","Foolish Baseball · Baseball Bits","https://www.youtube.com/watch?v=fJLf31q1_Qs","A swarm of bugs takes over a 2007 playoff game in Cleveland and rattles a rookie pitcher."],["v2","The Worst Call in MLB History: Why It Might Have Been Correct","Foolish Baseball · Baseball Bits","https://www.youtube.com/watch?v=YABX_zW-6Kc","The very first Baseball Bits. A famous umpire call, looked at from every angle."],["v3","The Royals Broke All the Rules (And Won)","Foolish Baseball · Baseball Bits","https://www.youtube.com/watch?v=L0bSAGd6_Zk","How a team won by playing a different style than everyone else."],["v4","The Hardest Thrower That Never Was","Foolish Baseball · Baseball Bits","https://www.youtube.com/watch?v=-zVGn_UxK7c","The story of a pitcher with a legendary arm."],["v5","The Future of Baseball Is International","Foolish Baseball · Baseball Bits","https://www.youtube.com/watch?v=aRh588oEiME","Baseball around the world, and where the next stars are coming from."],["v6","The Craziest GM in Sports","Foolish Baseball · Baseball Bits","https://www.youtube.com/watch?v=CZPDZQi8Ezw","How teams get built, through one very unusual general manager."]],"TIPS":["Hustle never has a bad day.","Be the teammate you'd want next to you.","The next pitch is the only one you can control.","Play catch like it matters. It does.","Good players practice until they get it right. Great players practice until they can't get it wrong.","Loud dugouts win games.","Eyes up, feet moving, glove down.","Have fun. It's a game. That's the whole point."],"PATH_N":3,"NOGEAR":"^(none|nothing|floor( space)?|open space|a wall|a quiet spot|20 feet of space|a parent|helper|a hallway|a phone or tablet)$"};
